
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)], uid=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,7), iso=(d=new Date())=>[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-'), esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
