function base_openHabit(id=''){let h=S.habits.find(x=>x.id===id)||{title:'',goalId:'',projectId:'',type:'check',target:1,unit:'session',freq:'daily',times:1,days:[],reminder:'',active:true};modal(id?'Modifier l’habitude':'Nouvelle habitude',`<div class="formgrid"><div class="span2"><label>Habitude *</label><input id="h_title" value="${esc(h.title)}"></div><div><label>Objectif lié</label><select id="h_goal">${opts(S.goals,h.goalId)}</select></div><div><label>Projet lié</label><select id="h_project">${opts(S.projects,h.projectId)}</select></div><div><label>Type de suivi</label><select id="h_type" onchange="habitTypeUI()"><option value="check">Validation simple</option><option value="timer" ${h.type==='timer'?'selected':''}>Minuteur / durée</option><option value="count" ${h.type==='count'?'selected':''}>Compteur / quantité</option><option value="session" ${h.type==='session'?'selected':''}>Sessions</option></select></div><div><label>Fréquence</label><select id="h_freq" onchange="habitFreqUI()"><option value="daily">Tous les jours</option><option value="weekly" ${h.freq==='weekly'?'selected':''}>X fois / semaine</option><option value="days" ${h.freq==='days'?'selected':''}>Jours précis</option><option value="weekdays" ${h.freq==='weekdays'?'selected':''}>Lun–Ven</option></select></div><div><label>Cible</label><input id="h_target" type="number" min="1" value="${h.target||1}"></div><div><label>Unité</label><input id="h_unit" value="${esc(h.unit||'session')}"></div><div><label>Nombre / semaine</label><input id="h_times" type="number" min="1" max="7" value="${h.times||1}"></div><div><label>Heure souhaitée (sans notification)</label><input id="h_reminder" type="time" value="${h.reminder||''}"></div><div class="span2"><label>Jours</label><div class="chips">${['Dim','Lun','Mar','Mer','Jeu','Ven','Sam'].map((x,i)=>`<label class="chip"><input style="width:auto" type="checkbox" name="hday" value="${i}" ${(h.days||[]).includes(i)?'checked':''}> ${x}</label>`).join('')}</div></div></div>`,`<button class="btn" onclick="closeModal()">Annuler</button><button class="btn primary" onclick="saveHabit('${id}')">Enregistrer</button>`)}function base_saveHabit(id){let title=$('#h_title').value.trim();if(!title)return toast('Nom obligatoire');let o={id:id||uid(),title,goalId:$('#h_goal').value,projectId:$('#h_project').value,type:$('#h_type').value,target:+$('#h_target').value||1,unit:$('#h_unit').value,freq:$('#h_freq').value,times:+$('#h_times').value||1,days:$$('input[name=hday]:checked').map(x=>+x.value),reminder:$('#h_reminder').value,active:true};let i=S.habits.findIndex(x=>x.id===id);i>=0?S.habits[i]=o:S.habits.push(o);save();closeModal();render();toast('Habitude enregistrée')}
function habitCount(id,n){return lastN(n).filter(d=>habitDone(id,d)).length}function lastN(n){return Array.from({length:n},(_,i)=>{let d=new Date();d.setDate(d.getDate()-(n-1-i));return iso(d)})}function last7(){return lastN(7)}
function habitTimer(id){let h=S.habits.find(x=>x.id===id);openFocusFor('habit',id,h?.target||S.settings.focus)}
function focusOptions(){let a=[`<option value="free">Session libre</option>`];S.tasks.filter(t=>t.status!=='done').forEach(x=>a.push(`<option value="task:${x.id}">Tâche · ${esc(x.title)}</option>`));S.projects.forEach(x=>a.push(`<option value="project:${x.id}">Projet · ${esc(x.title)}</option>`));S.goals.forEach(x=>a.push(`<option value="goal:${x.id}">Objectif · ${esc(x.title)}</option>`));S.habits.forEach(x=>a.push(`<option value="habit:${x.id}">Habitude · ${esc(x.title)}</option>`));return a.join('')}function fmt(s){return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')}function updateClock(){let e=$('#focusClock');if(e)e.textContent=fmt(focusRemain)}
function setSound(s){S.settings.sound=s;save();stopSound();if(s!=='none')startSound(s);render()}function startSound(type){audioCtx??=new (window.AudioContext||window.webkitAudioContext)();let buffer=audioCtx.createBuffer(1,audioCtx.sampleRate*2,audioCtx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1;let src=audioCtx.createBufferSource();src.buffer=buffer;src.loop=true;let filter=audioCtx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=type==='rain'?1200:type==='forest'?700:350;let gain=audioCtx.createGain();gain.gain.value=S.settings.volume*.25;src.connect(filter).connect(gain).connect(audioCtx.destination);src.start();noiseNode=gain;noiseNode._src=src}function stopSoundV5(){try{noiseNode?._src?.stop()}catch(e){}noiseNode=null}
function completionRate(){return S.tasks.length?Math.round(S.tasks.filter(t=>t.status==='done').length/S.tasks.length*100):0}function habitLinkedCompletions(gid){let ids=S.habits.filter(h=>h.goalId===gid).map(h=>h.id);return ids.reduce((a,id)=>a+habitCount(id,30),0)}
