// LifeOS V4 — calendrier local, historique réel et sessions persistantes
function load(){try{const raw=localStorage.getItem('lifeos.v4')||localStorage.getItem('lifeos.v3');if(!raw)return structuredClone(defaultState);return validateState(JSON.parse(raw))}catch(e){window.lifeLoadError=true;return structuredClone(defaultState)}}
function validateV4(o){if(!o||typeof o!=='object'||![3,4].includes(o.version))throw Error('Version de sauvegarde incompatible');const clean=JSON.parse(JSON.stringify(o),(k,v)=>['__proto__','constructor','prototype'].includes(k)?undefined:v);for(const k of ['tasks','goals','projects','habits','focus','journal']){if(!Array.isArray(clean[k]))throw Error('Liste manquante : '+k);if(clean[k].length>50000)throw Error('Trop de données');for(const x of clean[k]){if(!x||typeof x!=='object')throw Error('Élément invalide');if(k!=='journal'&&(!/^[a-zA-Z0-9_-]+$/.test(x.id)||typeof x.id!=='string'))throw Error('Identifiant invalide');if(['tasks','goals','projects','habits'].includes(k)&&typeof x.title!=='string')throw Error('Titre invalide');}if(k!=='journal'&&new Set(clean[k].map(x=>x.id)).size!==clean[k].length)throw Error('Identifiants dupliqués');}if(!clean.habitLogs||typeof clean.habitLogs!=='object'||Array.isArray(clean.habitLogs))throw Error('Historique invalide');for(const logs of Object.values(clean.habitLogs))for(const [d,v] of Object.entries(logs)){if(!/^\d{4}-\d{2}-\d{2}$/.test(d)||!v||!Number.isFinite(v.value)||v.value<0)throw Error('Valeur de suivi invalide');}for(const k of ['tasks','goals','projects','habits'])for(const x of clean[k]){for(const key of ['due','deadline','createdAt'])if(x[key]&&!/^\d{4}-\d{2}-\d{2}$/.test(x[key]))throw Error('Date invalide');for(const key of ['goalId','projectId'])if(x[key]&&!/^[a-zA-Z0-9_-]+$/.test(x[key]))throw Error('Liaison invalide');for(const key of ['estimate','target','times'])if(x[key]!==undefined&&(!Number.isFinite(x[key])||(key!=='target'&&x[key]<0)))throw Error('Nombre invalide');if(x.priority&&!['low','medium','high'].includes(x.priority))throw Error('Priorité invalide');if(x.reminder&&!/^\d{2}:\d{2}$/.test(x.reminder))throw Error('Heure invalide');}for(const j of clean.journal)if(typeof j.text!=='string'||typeof j.mood!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(j.date))throw Error('Journal invalide');for(const f of clean.focus)if(!Number.isFinite(f.minutes)||f.minutes<0||!/^\d{4}-\d{2}-\d{2}$/.test(f.date))throw Error('Session invalide');const s={...structuredClone(defaultState),...clean,version:4,settings:{...defaultState.settings,...clean.settings}};for(const k of ['focus','break','long'])if(!Number.isFinite(s.settings[k])||s.settings[k]<1||s.settings[k]>240)throw Error('Durée invalide');for(const g of s.goals)for(const k of ['start','target','current'])if(!Number.isFinite(g[k]))throw Error('Mesure objectif invalide');for(const h of s.habits){if(!Number.isFinite(h.target)||h.target<=0||!Number.isFinite(h.times)||h.times<1||h.times>7||!Array.isArray(h.days)||h.days.some(d=>!Number.isInteger(d)||d<0||d>6))throw Error('Habitude invalide');}s.theme=['light','midnight','forest','sunset','ocean'].includes(s.theme)?s.theme:'light';s.period=['day','week','month','quarter','year'].includes(s.period)?s.period:'week';return s;}
function persistState(){try{if(window.lifeLoadError){const raw=localStorage.getItem('lifeos.v4')||localStorage.getItem('lifeos.v3');if(raw)localStorage.setItem('lifeos.corrupt-recovery.v4',raw);window.lifeLoadError=false;}localStorage.setItem('lifeos.v4',JSON.stringify({...S,version:4}));}catch(e){alert('Sauvegarde impossible : stockage plein ou bloqué. Exporte tes données avant de fermer.');throw e;}}
function seed(){} // Aucun exemple ajouté automatiquement aux données personnelles.





function habitValue(id,d){return Number(S.habitLogs[id]?.[d]?.value)||0;}
function habitDone(id,d){const h=S.habits.find(x=>x.id===id);return !!h&&habitValue(id,d)>=(h.type==='check'?1:h.target);}
function logHabit(id){const h=S.habits.find(x=>x.id===id);modal('Suivi · '+esc(h.title),`<label>Date</label><input type="date" id="log_date" value="${iso()}" max="${iso()}" onchange="$('#log_value').value=habitValue('${id}',this.value)"><label style="margin-top:14px">Total de la journée (${esc(h.type==='timer'?'minutes':h.unit)}) · cible ${h.type==='check'?1:h.target}</label><input id="log_value" type="number" min="0" step="any" value="${habitValue(id,iso())}"><p class="muted" style="margin-top:12px">Saisis le total réalisé. Zéro retire la réalisation de cette journée.</p>`,`<button class="btn" onclick="closeModal()">Annuler</button><button class="btn primary" onclick="saveHabitLog('${id}')">Enregistrer</button>`);}
function saveHabitLog(id){const d=$('#log_date').value,v=Number($('#log_value').value);if(!d||d>iso()||!Number.isFinite(v)||v<0)return toast('Date ou quantité invalide');S.habitLogs[id]??={};if(v===0)delete S.habitLogs[id][d];else S.habitLogs[id][d]={value:v,at:Date.now()};save();closeModal();render();}



let plannerDate=iso(),statsDays=7;
function bounds(period,anchor){const d=new Date(anchor+'T12:00:00');let a=new Date(d),b=new Date(d);if(period==='week'){a.setDate(d.getDate()-((d.getDay()+6)%7));b=new Date(a);b.setDate(a.getDate()+6);}if(period==='month'){a=new Date(d.getFullYear(),d.getMonth(),1,12);b=new Date(d.getFullYear(),d.getMonth()+1,0,12);}if(period==='quarter'){let m=Math.floor(d.getMonth()/3)*3;a=new Date(d.getFullYear(),m,1,12);b=new Date(d.getFullYear(),m+3,0,12);}if(period==='year'){a=new Date(d.getFullYear(),0,1,12);b=new Date(d.getFullYear(),11,31,12);}return [iso(a),iso(b)];}
function movePeriod(n){let [a,b]=bounds(S.period,plannerDate),d=new Date((n>0?b:a)+'T12:00:00');d.setDate(d.getDate()+n);plannerDate=iso(d);render();}

function periodView(){const [a,b]=bounds(S.period,plannerDate),ts=S.tasks.filter(t=>t.due>=a&&t.due<=b),gs=S.goals.filter(g=>g.deadline>=a&&g.deadline<=b),mins=S.focus.filter(f=>f.date>=a&&f.date<=b).reduce((n,f)=>n+f.minutes,0);return `<p class="muted" style="margin-top:16px">Du ${a} au ${b}</p><div class="grid g3"><div class="card kpi">Tâches<strong>${ts.length}</strong></div><div class="card kpi">Objectifs à échéance<strong>${gs.length}</strong></div><div class="card kpi">Focus réalisé<strong>${mins} min</strong></div></div><div class="grid g2" style="margin-top:16px"><div class="card"><h3>Tâches de la période</h3><div class="list">${taskList(ts)||empty('Aucune tâche')}</div></div><div class="card"><h3>Objectifs</h3>${gs.map(goalCard).join('')||empty('Aucune échéance')}</div></div>`;}

function showFocusDay(d){modal('Sessions du '+d,S.focus.filter(f=>f.date===d).map(f=>`<div class="item">${esc(f.label)} · ${f.minutes} min</div>`).join('')||empty('Aucune session'));}
function focusMinutes(days){if(days<=0)return 0;const a=lastN(days)[0];return S.focus.filter(f=>f.date>=a&&f.date<=iso()).reduce((n,f)=>n+f.minutes,0);}
function focusFor(type,id){return S.focus.filter(f=>{if(f.type===type&&f.refId===id)return true;if(type==='goal'&&f.goalId===id||type==='project'&&f.projectId===id)return true;const k={task:'tasks',habit:'habits',project:'projects'}[f.type],x=k?S[k].find(x=>x.id===f.refId):null;return x&&(type==='goal'&&(x.goalId===id||S.projects.find(p=>p.id===x.projectId)?.goalId===id)||type==='project'&&x.projectId===id);}).reduce((n,f)=>n+f.minutes,0);}
let focusSession=null,focusSelection='free',focusMode='work';

function persistFocus(){try{localStorage.setItem('lifeos.timer.v4',JSON.stringify(focusSession));}catch(e){toast('Minuteur non sauvegardé');}}

function openFocusFor(type,id,mins){if(focusSession){go('focus');return toast('Termine ou réinitialise la session en cours');}focusMode='work';focusSelection=type+':'+id;focusRemain=(mins||S.settings.focus)*60;go('focus');}
function toggleFocusV5(){if(!focusSession){focusSelection=$('#focusLink')?.value||focusSelection;focusSession={id:uid(),selection:focusSelection,seconds:focusRemain,remaining:focusRemain,mode:focusMode,started:Date.now(),running:false};}if(focusRunning){tickFocus();if(!focusSession)return;focusSession.remaining=focusRemain;focusSession.running=false;clearInterval(focusInt);focusRunning=false;}else{focusSession.end=Date.now()+focusSession.remaining*1000;focusSession.running=true;focusRunning=true;clearInterval(focusInt);focusInt=setInterval(tickFocus,250);}persistFocus();render();}
function tickFocus(){if(!focusSession?.running)return;focusRemain=Math.max(0,Math.ceil((focusSession.end-Date.now())/1000));updateClock();if(focusRemain===0)completeFocus();}


function restoreBeforeImport(){const raw=localStorage.getItem('lifeos.before-import.v4');if(!raw)return toast('Aucune copie de récupération');if(!confirm('Remplacer les données actuelles par la copie conservée avant le dernier import ?'))return;try{const next=validateState(JSON.parse(raw));localStorage.setItem('lifeos.v4',JSON.stringify(next));location.reload();}catch(e){alert(e.message);}}



// Validation des formulaires et restauration de session.
function render(){base_render();if(current==='focus'&&$('#focusLink'))$('#focusLink').value=focusSession?.selection||focusSelection;$$('#mobilebar button').forEach(b=>b.classList.toggle('active',b.getAttribute('onclick')===`go('${current}')`));}


function validLinks(g,p){const project=S.projects.find(x=>x.id===$(p).value);if(project?.goalId){if($(g).value&&$(g).value!==project.goalId){toast('Le projet appartient à un autre objectif');return false;}$(g).value=project.goalId;}return true;}




document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});
// V6 — données, sauvegardes et intégration Android. État métier compatible V4.
const isNative=()=>!!window.Capacitor?.isNativePlatform?.();
const lifeosBridge=()=>isNative()?new Proxy({}, {get:(_,method)=>(args={})=>window.Capacitor.nativePromise('LifeOSNative',method,args)}):null;
let nativeInfo=null,nativeIssue='',nativeBusy=false,saveTimer=null;
const humanTime=x=>x?new Date(Number(x)).toLocaleString('fr-FR'):'Aucune';
const snapshotKey='lifeos.snapshots.v5';
function snapshots(){try{const x=JSON.parse(localStorage.getItem(snapshotKey)||'[]');return Array.isArray(x)?x:[]}catch{return []}}
function recordSnapshot(reason='Automatique',force=false){const list=snapshots(),now=Date.now();if(!force&&list.some(x=>x.day===iso()))return;list.unshift({id:uid(),day:iso(),at:now,reason,state:structuredClone(S)});localStorage.setItem(snapshotKey,JSON.stringify(list.slice(0,7)));}
function saveV5(){persistState();try{recordSnapshot();localStorage.setItem('lifeos.savedAt.v5',String(Date.now()));}catch{toast('Données enregistrées ; historique local plein. Exporte une sauvegarde.');}if(isNative()){clearTimeout(saveTimer);saveTimer=setTimeout(()=>stageNative().catch(e=>{nativeIssue=e.message;toast('Copie Android non actualisée : '+e.message)}),700);}}
function backupText(){return JSON.stringify({...S,productVersion:'6.4.5',stateUpdatedAt:Number(localStorage.getItem('lifeos.savedAt.v5')||0),exportedAt:new Date().toISOString()},null,2);}
async function stageNative(){return lifeosBridge()?.stageSnapshot({data:backupText()});}
async function refreshNative(){if(!isNative())return;try{nativeInfo=await lifeosBridge().status();nativeIssue='';}catch(e){nativeIssue=e.message||'Pont Android indisponible';}if(['data','settings'].includes(current))render();}
async function nativeAction(name,args={}){if(nativeBusy)return;nativeBusy=true;render();try{const r=await lifeosBridge()[name](args);await refreshNative();return r;}catch(e){alert(e.message||'Opération interrompue');}finally{nativeBusy=false;render();}}
function openSettings(){closeModal();go('settings');refreshNative();}

function settingsV5(){const n=nativeInfo;return `<div class="sectionhead"><div><div class="eyebrow">Ton espace personnel</div><h2>Paramètres & sécurité</h2></div><span class="tag">V6.4.5 · ${isNative()?'Android':'HTML / Web'}</span></div><div class="grid g2"><section class="card"><h3>Apparence</h3><p class="muted">Choisis une ambiance. Ton choix est enregistré automatiquement.</p><div class="themeChoices">${[['light','Clair','#6d5dfc'],['midnight','Minuit','#151a2e'],['forest','Forêt','#2e8b62'],['sunset','Soleil','#e96b4b'],['ocean','Océan','#1686a6']].map(([v,label,c])=>`<button class="themeChoice ${S.theme===v?'active':''}" onclick="setThemeV6('${v}')"><i style="background:${c}"></i>${label}${S.theme===v?' ✓':''}</button>`).join('')}</div><h3 style="margin-top:24px">Sessions de concentration</h3><p class="muted">Focus : ${S.settings.focus} min · Pause : ${S.settings.break} min</p><button class="btn" onclick="openTimerSettings()">Régler les durées</button></section><section class="card"><div class="eyebrow">Accès à l’application</div><h3 style="margin-top:10px">Biométrie ou code du téléphone</h3>${isNative()?`<p class="statusLine">${n?.lockEnabled?'● Verrouillage activé':'○ Verrouillage désactivé'}</p><p class="muted">Utilise l’empreinte, le visage compatible ou le code/PIN de ton téléphone. L’application se verrouille quand elle passe en arrière-plan.</p><div class="chips"><button class="btn primary" ${nativeBusy||!n||!n.canAuthenticate?'disabled':''} onclick="setNativeLock(${!n?.lockEnabled})">${n?.lockEnabled?'Désactiver le verrouillage':'Activer la biométrie / le PIN'}</button>${n?.lockEnabled?`<button class="btn" ${nativeBusy?'disabled':''} onclick="nativeAction('lockNow')">Verrouiller maintenant</button>`:''}</div>${n&&!n.canAuthenticate?'<p class="muted">Configure d’abord un code de verrouillage dans les réglages Android.</p>':''}`:`<p class="statusLine">Disponible dans l’application Android</p><p class="muted">Le fichier HTML local ne peut pas activer le verrouillage biométrique Android. Pour protéger l’accès à LifeOS, utilise la version Android.</p><p class="muted">Tu peux toutefois protéger tes fichiers de sauvegarde par un mot de passe dans « Données & sauvegardes ».</p>`}<p class="muted" style="margin-top:16px">Ce verrou protège l’ouverture de l’application. Il ne chiffre pas le stockage web de LifeOS. Les captures d’écran de l’APK sont bloquées.</p>${nativeIssue?`<p class="error">${esc(nativeIssue)}</p>`:''}</section><section class="card"><h3>Données personnelles</h3><p class="muted">Sans cloud activé, tes données restent sur cet appareil. Aucun compte n’est requis pour gérer tes objectifs.</p><button class="btn primary" onclick="go('data');refreshNative()">Données & sauvegardes →</button></section><section class="card"><h3>À propos</h3><p>LifeOS · Version 6.4.5</p><p class="muted">Une base commune HTML, PWA et Android. Les fonctionnalités qui nécessitent Android sont signalées explicitement.</p><button class="btn" onclick="showPrivacy()">Confidentialité & stockage</button></section></div>`;}
function setThemeV6(t){if(!['light','midnight','forest','sunset','ocean'].includes(t))return toast('Thème indisponible');S.theme=t;applyPreferences();save();render();toast('Thème appliqué');}
async function setNativeLock(enabled){if(enabled&&!confirm('Activer le verrouillage avec la biométrie ou le code de ton téléphone ?'))return;await nativeAction('setLock',{enabled});}
function dataV5(){const list=snapshots(),n=nativeInfo,counts=[['Objectifs',S.goals.length],['Projets',S.projects.length],['Tâches',S.tasks.length],['Habitudes',S.habits.length]];return `<div class="sectionhead"><div><div class="eyebrow">Conserver, transférer, récupérer</div><h2>Données & sauvegardes</h2></div><span class="tag">Enregistrement local automatique</span></div><div class="grid g4">${counts.map(([k,v])=>`<div class="card kpi"><small>${k}</small><strong>${v}</strong></div>`).join('')}</div><p class="muted" style="margin:16px 0">Dernier enregistrement : ${humanTime(localStorage.getItem('lifeos.savedAt.v5'))} · ${Math.ceil(new Blob([backupText()]).size/1024)} Ko · ${S.focus.length} sessions focus</p><div class="grid g2"><section class="card"><div class="eyebrow">Sur ton appareil</div><h3 style="margin-top:10px">Exporter & restaurer</h3><p class="muted">Enregistre une copie hors de l’application pour éviter de perdre tes données si tu effaces le stockage ou désinstalles LifeOS.</p><div class="actionStack"><button class="btn primary" onclick="exportData()">↓ Exporter la sauvegarde JSON</button><button class="btn" onclick="passwordExportDialog()">▣ Exporter avec mot de passe</button><button class="btn" onclick="importData()">↑ Restaurer un fichier JSON / protégé</button></div><p class="muted" style="margin-top:14px">Les exports JSON sont lisibles. Les exports protégés utilisent AES-GCM et nécessitent ton mot de passe à la restauration.</p></section><section class="card"><div class="eyebrow">Google Drive</div><h3 style="margin-top:10px">Synchronisation & sauvegarde</h3>${isNative()?`<p class="statusLine">${n?.driveConnected?'● Autorisation Google accordée':'○ Non connecté'}</p><p class="muted">Synchronise à la demande entre appareils : LifeOS compare les versions. Si Drive est plus récent, la restauration attend ta confirmation ; si cet appareil est plus récent, il envoie sa copie. Les modifications ne sont pas fusionnées.</p><div class="actionStack"><button class="btn primary" ${nativeBusy?'disabled':''} onclick="connectDrive()">${n?.driveConnected?'Vérifier la connexion Google':'Connecter Google Drive'}</button>${n?.driveConnected?`<button class="btn primary" ${nativeBusy?'disabled':''} onclick="syncDrive()">Synchroniser maintenant</button><button class="btn" ${nativeBusy?'disabled':''} onclick="backupDrive()">Sauvegarder maintenant</button><button class="btn" ${nativeBusy?'disabled':''} onclick="restoreDrive()">Restaurer depuis Drive</button><button class="btn" ${nativeBusy?'disabled':''} onclick="toggleAutoDrive()">${n.autoDrive?'Désactiver':'Activer'} la sauvegarde automatique (12 h)</button><button class="btn" ${nativeBusy?'disabled':''} onclick="disconnectDrive()">Arrêter les sauvegardes et déconnecter</button>`:''}</div><p class="muted">Dernier envoi réussi : ${humanTime(n?.lastCloudAt)}<br>État : ${esc(n?.cloudStatus||'Aucune sauvegarde cloud')}<br>Sauvegarde automatique : ${n?.autoDrive?'activée, selon la disponibilité réseau et Android':'désactivée'}</p><small class="muted">Google Drive doit être activé dans le projet Google Cloud de l’APK ; l’identité OAuth Android doit correspondre au certificat de signature. La connexion te signalera une configuration manquante.</small>`:`<p class="statusLine">Disponible dans l’application Android</p><p class="muted">Sur Android, connecte Drive pour synchroniser les versions à la demande, sauvegarder automatiquement et restaurer une copie. Dans ce fichier HTML, exporte puis importe un fichier JSON.</p>`}<p class="muted" style="margin-top:12px">Les sauvegardes Drive sont des fichiers JSON dans l’espace privé de l’application, sans chiffrement par mot de passe ajouté par LifeOS. Un export protégé reste possible séparément.</p></section><section class="card"><h3>Points de récupération locaux</h3><p class="muted">Jusqu’à 7 copies : une par jour à la première modification, plus les copies manuelles. Elles restent dans ce même navigateur et ne remplacent pas un export externe.</p><button class="btn" onclick="manualSnapshot()">Créer un point maintenant</button><div class="list" style="margin-top:14px">${list.map(x=>`<div class="item"><div class="grow"><b>${humanTime(x.at)}</b><small>${esc(x.reason)}</small></div><button class="btn" onclick="restoreSnapshot('${x.id}')">Restaurer</button></div>`).join('')||empty('Aucun point de récupération')}</div><button class="btn" style="margin-top:14px" onclick="recoverPrevious()">Récupérer l’état avant le dernier import</button></section><section class="card"><h3>Gestion & confidentialité</h3><p class="muted">Les fonctions existantes et les données V3/V4 sont conservées. Une restauration remplace les données après validation et confirmation.</p><button class="btn" onclick="showPrivacy()">Comprendre le stockage</button><hr style="border:0;border-top:1px solid var(--line);margin:24px 0"><h3>Réinitialisation</h3><p class="muted">Effacer les données métier de cet appareil. Les points locaux sont conservés pour récupération ; les sauvegardes cloud ne sont pas supprimées.</p><button class="btn danger" onclick="resetDialog()">Réinitialiser les données…</button></section></div>`;}
function showPrivacy(){modal('Confidentialité & stockage',`<p>Les objectifs, habitudes, tâches, journal et sessions sont enregistrés dans le stockage local du navigateur ou de l’APK.</p><p>La biométrie Android protège l’accès à l’interface ; ce n’est pas un chiffrement du stockage web. La copie de travail utilisée par le service de sauvegarde Android est chiffrée au repos avec Android Keystore.</p><p>Google Drive n’est contacté qu’après ton activation. Le cloud reçoit une copie JSON de toutes tes données métier, y compris le journal. Aucun secret OAuth n’est intégré au HTML.</p><p>Un export protégé est chiffré avec un mot de passe non conservé. Sans ce mot de passe, aucune récupération de ce fichier n’est possible.</p><p>Les données peuvent disparaître si tu effaces le stockage ou désinstalles l’application. Garde une copie externe.</p>`);}
function manualSnapshot(){try{recordSnapshot('Copie manuelle',true);render();toast('Point de récupération créé');}catch{alert('Espace local insuffisant. Exporte un fichier.');}}
async function restoreSnapshot(id){const x=snapshots().find(x=>x.id===id);if(x)await applyBackup(x.state);}
async function recoverPrevious(){try{const raw=localStorage.getItem('lifeos.before-import.v4');if(!raw)return toast('Aucune copie disponible');await applyBackup(JSON.parse(raw));}catch(e){alert(e.message);}}
async function applyBackupV5(raw){const next=validateState(raw);if(!confirm(`Restaurer ${next.goals.length} objectifs, ${next.tasks.length} tâches et ${next.habits.length} habitudes ? Les données actuelles seront remplacées.`))return false;const old=JSON.stringify(S);localStorage.setItem('lifeos.before-import.v4',old);localStorage.setItem('lifeos.v4',JSON.stringify(next));S=next;clearInterval(focusInt);focusSession=null;focusRunning=false;persistFocus();focusRemain=S.settings.focus*60;document.documentElement.dataset.theme=S.theme==='light'?'':S.theme;save();closeModal();go('data');toast('Données restaurées');return true;}
function resetDialog(){modal('Réinitialiser les données',`<p>Un point de récupération sera créé avant de vider tes données métier. La sauvegarde automatique Drive sera arrêtée pour préserver ta copie cloud.</p><label>Tape EFFACER pour confirmer</label><input id="resetConfirm" autocomplete="off">`,`<button class="btn" onclick="closeModal()">Annuler</button><button class="btn danger" onclick="resetBusinessData()">Confirmer la réinitialisation</button>`);}
async function resetBusinessDataV5(){if($('#resetConfirm').value!=='EFFACER')return toast('Tape EFFACER en majuscules');try{if(isNative()&&nativeInfo?.autoDrive){await lifeosBridge().setAutoBackup({enabled:false});await refreshNative();}recordSnapshot('Avant réinitialisation',true);localStorage.setItem('lifeos.before-import.v4',JSON.stringify(S));S={...structuredClone(defaultState),theme:S.theme};clearInterval(focusInt);focusSession=null;focusRunning=false;persistFocus();focusRemain=S.settings.focus*60;save();closeModal();go('data');}catch(e){alert('Réinitialisation interrompue : '+e.message);}}
async function saveFile(text,name){if(isNative()){await lifeosBridge().exportFile({data:text,name});toast('Fichier enregistré');}else{const u=URL.createObjectURL(new Blob([text],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),30000);}}
async function exportData(){try{await saveFile(backupText(),'LifeOS-V6-'+iso()+'.json');}catch(e){alert(e.message||'Export annulé');}}
function bytes64(b){let s='';for(let i=0;i<b.length;i+=8192)s+=String.fromCharCode(...b.subarray(i,i+8192));return btoa(s);}
function from64(s){return Uint8Array.from(atob(s),x=>x.charCodeAt(0));}
async function deriveKey(password,salt){const base=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:310000,hash:'SHA-256'},base,{name:'AES-GCM',length:256},false,['encrypt','decrypt']);}
async function sealBackup(text,password){if(new TextEncoder().encode(text).length>14000000)throw Error('Données trop volumineuses pour un export protégé (14 Mo maximum).');if(!crypto?.subtle)throw Error('Chiffrement non disponible dans ce navigateur. Ouvre le fichier dans Chrome ou utilise l’APK.');if(password.length<12)throw Error('Utilise au moins 12 caractères');const salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),key=await deriveKey(password,salt),data=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,new TextEncoder().encode(text));return {format:'LifeOS.EncryptedBackup',version:1,kdf:'PBKDF2-SHA256',iterations:310000,salt:bytes64(salt),iv:bytes64(iv),data:bytes64(new Uint8Array(data))};}
async function unsealBackup(o,password){if(o.format!=='LifeOS.EncryptedBackup'||o.version!==1||o.iterations!==310000||o.kdf!=='PBKDF2-SHA256'||typeof o.data!=='string'||o.data.length>28000000)throw Error('Format chiffré incompatible');const salt=from64(o.salt),iv=from64(o.iv);if(salt.length!==16||iv.length!==12)throw Error('Fichier chiffré invalide');try{const key=await deriveKey(password,salt),plain=await crypto.subtle.decrypt({name:'AES-GCM',iv},key,from64(o.data));return JSON.parse(new TextDecoder().decode(plain));}catch{throw Error('Mot de passe incorrect ou fichier altéré');}}
function passwordExportDialog(){modal('Exporter une sauvegarde protégée',`<p>Choisis un mot de passe d’au moins 12 caractères. Il ne sera pas enregistré et ne pourra pas être récupéré.</p><label>Mot de passe</label><input type="password" id="backupPassword" autocomplete="new-password"><label style="margin-top:14px">Confirmer</label><input type="password" id="backupPassword2" autocomplete="new-password"><p id="cryptoMessage" class="error" role="status"></p>`,`<button class="btn" onclick="closeModal()">Annuler</button><button class="btn primary" id="encryptButton" onclick="encryptAndExport()">Chiffrer et exporter</button>`);}
async function encryptAndExport(){const p=$('#backupPassword').value;if(p!==$('#backupPassword2').value)return $('#cryptoMessage').textContent='Les mots de passe diffèrent';const b=$('#encryptButton');b.disabled=true;try{const o=await sealBackup(backupText(),p);await saveFile(JSON.stringify(o),'LifeOS-protege-'+iso()+'.json');closeModal();}catch(e){$('#cryptoMessage').textContent=e.message;}finally{b.disabled=false;}}
let pendingEncrypted=null;
async function receiveBackupText(text){if(text.length>20000000)throw Error('Fichier trop volumineux (20 Mo maximum)');const o=JSON.parse(text);if(o.format==='LifeOS.EncryptedBackup'){pendingEncrypted=o;modal('Déverrouiller la sauvegarde',`<label>Mot de passe de la sauvegarde</label><input type="password" id="restorePassword" autocomplete="off"><p class="error" id="decryptMessage" role="status"></p>`,`<button class="btn" onclick="pendingEncrypted=null;closeModal()">Annuler</button><button class="btn primary" id="decryptButton" onclick="decryptAndRestore()">Déchiffrer</button>`);}else await applyBackup(o);}
async function decryptAndRestore(){const b=$('#decryptButton');b.disabled=true;try{const o=await unsealBackup(pendingEncrypted,$('#restorePassword').value);if(await applyBackup(o))pendingEncrypted=null;}catch(e){$('#decryptMessage').textContent=e.message;}finally{b.disabled=false;}}
async function importData(){try{if(isNative()){const r=await lifeosBridge().importFile();await receiveBackupText(r.data);}else{const i=document.createElement('input');i.type='file';i.accept='.json,application/json';i.onchange=async()=>{try{const f=i.files[0];if(!f)return;if(f.size>20000000)throw Error('Fichier trop volumineux');await receiveBackupText(await f.text());}catch(e){alert('Import refusé : '+e.message)}};i.click();}}catch(e){alert('Import interrompu : '+e.message);}}
async function connectDrive(){await stageNative();await nativeAction('drive',{action:'connect'});}
async function backupDrive(){if(!confirm('Envoyer toutes tes données LifeOS, y compris le journal, vers ton espace privé Google Drive ?'))return;try{await stageNative();await nativeAction('drive',{action:'backup'});}catch(e){alert(e.message);}}
async function syncDrive(){if(!confirm('Comparer les données locales et Drive ? Si Drive est plus récent, LifeOS demandera confirmation avant de remplacer les données de cet appareil. Si cet appareil est plus récent, sa copie sera envoyée sur Drive. Les données ne sont pas fusionnées.'))return;try{await stageNative();const r=await nativeAction('drive',{action:'sync'});if(!r)return;if(r.data)await receiveBackupText(r.data);else toast(nativeInfo?.cloudStatus||'Synchronisation terminée');}catch(e){alert(e.message||'Synchronisation interrompue');}}
async function restoreDrive(){const r=await nativeAction('drive',{action:'restore'});if(r?.data)try{await receiveBackupText(r.data);}catch(e){alert('Sauvegarde Drive invalide : '+e.message);}}
async function toggleAutoDrive(){const enabled=!nativeInfo?.autoDrive;if(enabled&&!confirm('Autoriser l’envoi automatique de toutes tes données LifeOS sur ton Drive environ toutes les 12 heures ?'))return;try{await stageNative();await nativeAction('setAutoBackup',{enabled});}catch(e){alert(e.message);}}
async function disconnectDrive(){if(!confirm('Arrêter les envois et retirer l’autorisation Google ? Les sauvegardes déjà présentes sur Drive seront conservées.'))return;await nativeAction('drive',{action:'disconnect'});}
async function bootV5(){await refreshNative();if(isNative()){try{await stageNative();}catch(e){nativeIssue=e.message;}}else if(location.protocol!=='file:'&&'serviceWorker' in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});}
window.addEventListener('lifeos-unlocked',()=>{refreshNative();stageNative().catch(e=>{nativeIssue=e.message;});});
window.addEventListener('focus',()=>{if(['settings','data'].includes(current))refreshNative();});

window.lifeosHandleBack=()=>{if($('#modalBack').classList.contains('open')){closeModal();return true;}if($('#side').classList.contains('open')){closeSide();return true;}if(current!=='today'){go('today');return true;}return false;};

// V6 domain model: migration, relationships, recurrence, progress and recovery.
function upgradeState(s){
 s.productVersion='6.4.5';s.trash=Array.isArray(s.trash)?s.trash:[];s.reviews=Array.isArray(s.reviews)?s.reviews:[];
 s.settings={density:'comfortable',favorites:['tasks','habits','planner'],domains:['Santé','Famille','Carrière','Finance','Développement','Spiritualité','Relations','Loisirs'],notifications:false,autoCycles:false,cycles:4,...s.settings};
 for(const t of s.tasks){t.subtasks??=[];t.repeat??='none';t.dueTime??='';t.remind??=false;t.completedAt??=null;}
 for(const p of s.projects)p.milestones??=[];
 for(const g of s.goals){g.icon??='🎯';g.progressMode??='manual';g.history??=[];g.createdAt??=iso();g.habitWindow??=30;}
 for(const h of s.habits){h.icon??='🔁';h.monthDays??=[1];h.pauses??=[];h.createdAt??=iso();}
 const fixes=reconcileLinks(s);if(fixes)s.migrationNote=`${fixes} liaison(s) harmonisée(s) avec l’objectif du projet parent.`;
 return s;
}
function validateState(raw){const s=validateV4(raw),id=x=>typeof x==='string'&&/^[A-Za-z0-9_-]+$/.test(x),date=x=>!x||(/^\d{4}-\d{2}-\d{2}$/.test(x)&&iso(new Date(x+'T12:00:00'))===x),array=(v,key)=>{if(v!==undefined&&!Array.isArray(v))throw Error(key+' doit être une liste');};
 for(const t of s.tasks){if(t.repeat&&!['none','daily','weekly','monthly','weekdays'].includes(t.repeat))throw Error('Récurrence inconnue');if(t.dueTime&&!/^([01]\d|2[0-3]):[0-5]\d$/.test(t.dueTime))throw Error('Heure de tâche invalide');if(!date(t.due))throw Error('Date de tâche invalide');if(t.completedAt&&!Number.isFinite(Date.parse(t.completedAt)))throw Error('Date de réalisation invalide');array(t.subtasks,'Sous-tâches');for(const x of t.subtasks||[])if(!id(x.id)||typeof x.title!=='string')throw Error('Sous-tâche invalide');}
 for(const p of s.projects){array(p.milestones,'Jalons');for(const m of p.milestones||[])if(!id(m.id)||typeof m.title!=='string'||!date(m.due))throw Error('Jalon invalide');}
 for(const g of s.goals){if(g.progressMode&&!['manual','tasks','habits','focus'].includes(g.progressMode))throw Error('Mode de progression invalide');array(g.history,'Historique objectif');for(const x of g.history||[])if(!date(x.date)||!Number.isFinite(x.value)||x.value<0||x.value>100)throw Error('Historique objectif invalide');if(g.habitWindow!==undefined&&![7,30,90].includes(g.habitWindow))throw Error('Période habitude invalide');}
 for(const h of s.habits){if(!['daily','weekly','days','weekdays','monthly'].includes(h.freq))throw Error('Fréquence inconnue');array(h.monthDays,'Jours mensuels');if(h.monthDays?.some(d=>!Number.isInteger(d)||d<1||d>31))throw Error('Jour mensuel invalide');array(h.pauses,'Pauses');for(const p of h.pauses||[])if(!date(p.start)||!p.start||!date(p.end)||(p.end&&p.end<p.start))throw Error('Pause invalide');}
 array(s.reviews,'Revues');for(const r of s.reviews||[])if(!date(r.week)||typeof r.wins!=='string'||typeof r.next!=='string')throw Error('Revue invalide');
 // Trash payloads are never trusted for restoration; each restoration validates a full candidate.
 array(s.trash,'Corbeille');if((s.trash||[]).some(t=>!id(t.id)||!['task','goal','project','habit','journal'].includes(t.type)||!t.item||typeof t.item!=='object'))throw Error('Corbeille invalide');
 if(s.settings.domains!==undefined&&(!Array.isArray(s.settings.domains)||s.settings.domains.some(x=>typeof x!=='string'||x.length>60)))throw Error('Domaines invalides');
 const allowed=['tasks','goals','habits','planner','focus','journal','projects','stats','data','settings','coach'];if(s.settings.favorites!==undefined&&(!Array.isArray(s.settings.favorites)||s.settings.favorites.length!==3||new Set(s.settings.favorites).size!==3||s.settings.favorites.some(x=>!allowed.includes(x))))throw Error('Favoris invalides');
 if(s.settings.density!==undefined&&!['compact','comfortable'].includes(s.settings.density))throw Error('Densité invalide');
 return upgradeState(s);
}
function reconcileLinks(s=S){let n=0;const goals=new Set(s.goals.map(x=>x.id)),projects=new Map(s.projects.map(x=>[x.id,x]));for(const p of s.projects)if(p.goalId&&!goals.has(p.goalId)){p.goalId='';n++;}for(const k of ['tasks','habits'])for(const x of s[k]){if(x.projectId&&!projects.has(x.projectId)){x.projectId='';n++;}const p=projects.get(x.projectId);const desired=p?p.goalId:(goals.has(x.goalId)?x.goalId:'');if((x.goalId||'')!==(desired||'')){x.goalId=desired||'';n++;}}return n;}
function localDay(isoTimestamp){return isoTimestamp?iso(new Date(isoTimestamp)):'';}
function taskRank(t){return (t.due&&t.due<iso()?1000:0)+({high:100,medium:50,low:10}[t.priority]||0)+(t.due===iso()?20:0);}
function rankedTasks(arr){return [...arr].sort((a,b)=>taskRank(b)-taskRank(a)||(a.due||'9999').localeCompare(b.due||'9999')||(a.dueTime||'99').localeCompare(b.dueTime||'99')||a.title.localeCompare(b.title));}
function todayTasks(){return rankedTasks(S.tasks.filter(t=>t.status!=='done'&&t.due&&t.due<=iso()));}
function nextRepeatDate(t,after=iso()){
 if(!t.due||!t.repeat||t.repeat==='none')return '';
 let d=new Date(t.due+'T12:00:00');const anchor=t.repeatDay||d.getDate();
 for(let i=0;i<50000;i++){if(t.repeat==='monthly'){const y=d.getFullYear(),m=d.getMonth()+1;d=new Date(y,m,Math.min(anchor,new Date(y,m+1,0).getDate()),12);}else{d.setDate(d.getDate()+(t.repeat==='weekly'?7:1));if(t.repeat==='weekdays')while([0,6].includes(d.getDay()))d.setDate(d.getDate()+1);}if(iso(d)>after)return iso(d);}throw Error('Récurrence trop ancienne');
}
function setTaskStatus(id,status,{silent=false}={}){const t=S.tasks.find(x=>x.id===id);if(!t)return;const previous=t.status;t.status=status;
 if(status==='done'&&previous!=='done'){t.completedAt=new Date().toISOString();if(t.repeat&&t.repeat!=='none'&&!t.nextId){const date=nextRepeatDate(t);if(date){const n={...structuredClone(t),id:uid(),due:date,status:'todo',completedAt:null,createdAt:iso(),seriesId:t.seriesId||t.id,previousId:t.id,nextId:null,repeatDay:t.repeatDay||Number(t.due.slice(-2)),subtasks:(t.subtasks||[]).map(s=>({...s,id:uid(),done:false}))};t.nextId=n.id;t.seriesId=n.seriesId;S.tasks.push(n);}}}
 if(status!=='done')t.completedAt=null;if(!silent){save();render();}
}
function toggleTask(id){const t=S.tasks.find(x=>x.id===id);if(t)setTaskStatus(id,t.status==='done'?'todo':'done');}
function toggleSubtask(tid,sid){const t=S.tasks.find(x=>x.id===tid),s=t?.subtasks.find(x=>x.id===sid);if(s){s.done=!s.done;save();render();}}
function postponeTask(id){const t=S.tasks.find(x=>x.id===id);if(!t)return;t.due=addDays(1);save();render();toast('Reportée à demain');}
function linkItem(type,id,gid,on){const key={project:'projects',task:'tasks',habit:'habits'}[type],x=S[key]?.find(x=>x.id===id);if(!x)return;const next=on?gid:'';if(type!=='project'&&x.projectId){const p=S.projects.find(p=>p.id===x.projectId);if(p&&p.goalId!==next){toast('Modifie l’objectif du projet parent pour garder une liaison cohérente.');openLinked(gid);return;}}x.goalId=next;if(type==='project')for(const k of ['tasks','habits'])S[k].filter(t=>t.projectId===id).forEach(t=>t.goalId=next);save();}
function pausedOn(h,d){return (h.pauses||[]).some(p=>p.start<=d&&(!p.end||p.end>=d));}
function scheduled(h,d){const day=new Date(d+'T12:00:00').getDay();return h.active&&(!h.createdAt||d>=h.createdAt)&&!pausedOn(h,d)&&(h.freq==='weekdays'?day>=1&&day<=5:h.freq==='days'?h.days.includes(day):h.freq==='monthly'?(h.monthDays||[]).includes(Number(d.slice(-2))):true);}
function datesBetween(a,b){const dates=[];let d=new Date(a+'T12:00:00');while(iso(d)<=b&&dates.length<3660){dates.push(iso(d));d.setDate(d.getDate()+1);}return dates;}
function habitPeriod(h,a,b){const dates=datesBetween(a,b).filter(d=>scheduled(h,d));if(h.freq!=='weekly')return {expected:dates.length,done:dates.filter(d=>habitDone(h.id,d)).length};const groups={};for(const d of dates){const k=bounds('week',d)[0];(groups[k]??=[]).push(d);}let expected=0,done=0;for(const ds of Object.values(groups)){const target=Math.min(h.times,ds.length);expected+=target;done+=Math.min(target,ds.filter(d=>habitDone(h.id,d)).length);}return {expected,done};}
function pctGoal(g){let value=0;if(g.progressMode==='tasks'){const ts=S.tasks.filter(t=>t.goalId===g.id);value=ts.length?100*ts.filter(t=>t.status==='done').length/ts.length:0;}else if(g.progressMode==='habits'){const ds=lastN(g.habitWindow||30),hs=S.habits.filter(h=>h.goalId===g.id);let e=0,d=0;for(const h of hs){const p=habitPeriod(h,ds[0],iso());e+=p.expected;d+=p.done;}value=e?100*d/e:0;}else if(g.progressMode==='focus')value=g.target>0?100*focusFor('goal',g.id)/g.target:0;else value=g.target!==g.start?100*(g.current-g.start)/(g.target-g.start):(g.status==='done'?100:0);return Math.round(Math.max(0,Math.min(100,value)));}
function captureGoalHistory(){for(const g of S.goals){g.history??=[];const last=g.history.at(-1),value=pctGoal(g);if(!last||last.value!==value||last.date!==iso()){g.history.push({date:iso(),at:new Date().toISOString(),value});if(g.history.length>1000)g.history.shift();}}}
function save(){reconcileLinks();captureGoalHistory();saveV5();clearTimeout(reminderDebounce);reminderDebounce=setTimeout(()=>syncReminders().catch(e=>{reminderStatus=e.message;}),900);}
function del(type,id){const key={task:'tasks',goal:'goals',project:'projects',habit:'habits',journal:'journal'}[type];if(!key)return;const item=S[key].find(x=>(type==='journal'?x.date:x.id)===id);if(!item||!confirm('Déplacer cet élément dans la corbeille ? Les éléments liés seront conservés.'))return;
 const links=[];for(const k of ['tasks','habits','projects'])for(const x of S[k])if((type==='goal'&&x.goalId===id)||(type==='project'&&x.projectId===id))links.push({collection:k,id:x.id,goalId:x.goalId||'',projectId:x.projectId||''});
 const entry={id:uid(),type,item:structuredClone(item),deletedAt:new Date().toISOString(),links,logs:type==='habit'?structuredClone(S.habitLogs[id]||{}):null};S.trash.unshift(entry);S[key]=S[key].filter(x=>(type==='journal'?x.date:x.id)!==id);if(type==='habit')delete S.habitLogs[id];if(type==='goal')for(const k of ['tasks','habits','projects'])S[k].filter(x=>x.goalId===id).forEach(x=>x.goalId='');if(type==='project')for(const k of ['tasks','habits'])S[k].filter(x=>x.projectId===id).forEach(x=>x.projectId='');save();closeModal();render();toast('Déplacé dans la corbeille — restauration dans Données');}
function restoreTrash(id){const entry=S.trash.find(x=>x.id===id);if(!entry)return;const key={task:'tasks',goal:'goals',project:'projects',habit:'habits',journal:'journal'}[entry.type],candidate=structuredClone(S),item=entry.item;if(candidate[key].some(x=>(entry.type==='journal'?x.date:x.id)===(entry.type==='journal'?item.date:item.id)))return toast('Un élément identique existe déjà');candidate[key].push(structuredClone(item));if(entry.type==='habit')candidate.habitLogs[item.id]=entry.logs||{};candidate.trash=candidate.trash.filter(x=>x.id!==id);
 // Relink only records still detached; do not overwrite newer user choices.
 for(const l of entry.links||[]){if(!['tasks','habits','projects'].includes(l.collection))continue;const x=candidate[l.collection].find(x=>x.id===l.id);if(!x)continue;if(entry.type==='goal'&&!x.goalId)x.goalId=item.id;if(entry.type==='project'&&!x.projectId){x.projectId=item.id;x.goalId=item.goalId||'';}}
 try{S=validateState(candidate);save();render();toast('Élément restauré');}catch(e){alert('Restauration impossible : '+e.message);}}
function purgeTrash(id){if(!confirm('Supprimer définitivement cet élément de la corbeille ?'))return;S.trash=S.trash.filter(x=>x.id!==id);save();render();}
function toggleHabitPause(id){const h=S.habits.find(h=>h.id===id);if(!h)return;if(!h.active){h.active=true;save();render();return;}const p=h.pauses.find(x=>!x.end);if(p){const d=new Date();d.setDate(d.getDate()-1);if(p.start>iso(d))h.pauses=h.pauses.filter(x=>x!==p);else p.end=iso(d);}else h.pauses.push({start:iso(),end:''});save();render();}
function summaryPeriod(a,b){const tasks=S.tasks.filter(t=>t.status==='done'&&t.completedAt&&localDay(t.completedAt)>=a&&localDay(t.completedAt)<=b),focus=S.focus.filter(f=>f.date>=a&&f.date<=b);let done=0,expected=0;for(const h of S.habits){const p=habitPeriod(h,a,b);done+=p.done;expected+=p.expected;}return {tasks:tasks.length,minutes:Math.round(focus.reduce((n,f)=>n+f.minutes,0)),sessions:focus.length,estimated:tasks.reduce((n,t)=>n+(t.estimate||0),0),actualForTasks:Math.round(tasks.reduce((n,t)=>n+focusFor('task',t.id),0)),habits:expected?Math.round(100*done/expected):null,habitDone:done,habitExpected:expected};}

// V6 UI: shared icon language, actionable home, task management, goal execution.
const iconPaths={today:'M3 10 12 3l9 7M5 9v12h5v-7h4v7h5V9',tasks:'m4 12 5 5L20 5',goals:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10M12 11v2',projects:'M3 7h7l2-3h9v17H3z',habits:'M20 7a8 8 0 0 0-14-2L3 8m0-5v5h5m-4 9a8 8 0 0 0 14 2l3-3m0 5v-5h-5',planner:'M4 5h16v16H4zM4 10h16M8 3v4m8-4v4',focus:'M12 5a8 8 0 1 0 0 16 8 8 0 0 0 0-16M9 2h6m-3 6v5l3 2',journal:'M5 3h14v18H5zM8 7h8M8 11h8M8 15h5',stats:'M4 20V10m6 10V4m6 16v-7m6 7H2',coach:'M12 3 9 9l-6 3 6 3 3 6 3-6 6-3-6-3z',data:'M4 5h16v15H4zM4 9h16m-9 4h3',settings:'M12 3v3m0 12v3M3 12h3m12 0h3M5.6 5.6l2.1 2.1m8.6 8.6 2.1 2.1m0-12.8-2.1 2.1m-8.6 8.6-2.1 2.1M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8',more:'M4 6h16M4 12h16M4 18h16',edit:'m4 16 12-12 4 4L8 20H4z',trash:'M4 6h16M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7',add:'M12 4v16M4 12h16',arrow:'M4 12h16m-6-6 6 6-6 6'};
function icon(name){return `<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${iconPaths[name]||iconPaths.more}"/></svg>`;}
function iconButton(name,label,action){return `<button title="${esc(label)}" aria-label="${esc(label)}" onclick="${action}">${icon(name)}</button>`;}
function init(){S=upgradeState(S);applyPreferences();$('#dateLine').textContent=new Intl.DateTimeFormat('fr-FR',{weekday:'long',day:'numeric',month:'long'}).format(new Date());renderNav();go('today');window.lifeosStartupReady=true;if(S.migrationNote)toast(S.migrationNote);}
function applyPreferences(){const theme=['light','midnight','forest','sunset','ocean'].includes(S.theme)?S.theme:'light';S.theme=theme;document.documentElement.dataset.theme=theme==='light'?'':theme;document.documentElement.dataset.density=S.settings.density||'comfortable';}
function renderNav(){const groups=[['Agir',['today','tasks','habits','planner','focus']],['Construire',['goals','projects','journal']],['Prendre du recul',['stats','coach']],['Mon espace',['data','settings']]];$('#nav').innerHTML=groups.map(([label,ids])=>`<div class="navGroup">${label}</div>${ids.map(id=>{const n=navs.find(n=>n[0]===id);return `<button data-v="${id}" onclick="go('${id}')" title="${esc(n[2])}">${icon(id)}<span>${n[2]}</span></button>`;}).join('')}`).join('');const ids=['today',...(S.settings.favorites||['tasks','habits','planner']),'more'];$('#mobilebar').innerHTML=ids.map(id=>{const label=id==='more'?'Plus':id==='today'?'Jour':navs.find(n=>n[0]===id)?.[2]||id;return `<button onclick="go('${id}')" aria-label="${esc(label)}">${icon(id)}<span>${esc(label)}</span></button>`;}).join('');}
function renderMoreBaseV6(){return `<div class="pageIntro"><div class="eyebrow">Tous tes espaces</div><h2>Que souhaites-tu faire ?</h2><p class="muted">Tes trois raccourcis favoris se règlent dans Paramètres.</p></div><div class="grid g2">${navs.map(([id,,name])=>`<button class="card menuTile" onclick="go('${id}');if(['settings','data'].includes('${id}'))refreshNative()">${icon(id)}<b>${esc(name)}</b>${icon('arrow')}</button>`).join('')}</div>`;}
let selectedTaskIds=new Set(),taskFilters={q:'',status:'open',priority:'all',project:'all',sort:'priority'},projectMode='cards',calendarMode='month',selectedDay=iso(),journalDate=iso(),journalSearch='';
const priorityName=v=>({high:'Haute',medium:'Normale',low:'Basse'}[v]||'Normale');
const repeatName=v=>({none:'Sans récurrence',daily:'Chaque jour',weekdays:'Lun–Ven',weekly:'Chaque semaine',monthly:'Chaque mois'}[v]||'Sans récurrence');
function renderToday(){const due=S.tasks.filter(t=>t.due===iso()),done=due.filter(t=>t.status==='done').length,top=todayTasks().slice(0,3),habits=S.habits.filter(h=>scheduled(h,iso())),late=S.tasks.filter(t=>t.status!=='done'&&t.due&&t.due<iso()).length,week=summaryPeriod(bounds('week',iso())[0],iso());return `<div class="homeHero"><div><div class="eyebrow">Une direction claire. Une action à la fois.</div><h2>Ta journée, à l’essentiel.</h2><p>${top.length?`Commence par <strong>${esc(top[0].title)}</strong>.`:'Choisis une action qui fait avancer ton objectif.'}</p><div class="chips"><button class="btn primary" onclick="${top.length?`openFocusFor('task','${top[0].id}')`:'openTask()'}">${icon('focus')} ${top.length?'Commencer une session':'Planifier une action'}</button><button class="btn" onclick="go('planner')">Voir mon calendrier</button></div></div><div class="dailyScore"><strong>${done}<span> / ${due.length}</span></strong><p>tâches du jour terminées</p><div class="progress"><span style="width:${due.length?done/due.length*100:0}%"></span></div>${late?`<button class="textButton" onclick="taskFilters.status='late';go('tasks')">${late} tâche(s) en retard →</button>`:'<small>Pas de tâche en retard</small>'}</div></div><div class="homeColumns"><section><div class="sectionhead"><h2>Mes 3 priorités</h2><button class="textButton" onclick="go('tasks')">Toutes les tâches →</button></div><p class="muted caption">Retards, priorité, puis échéance. Les tâches sans date restent dans la liste générale.</p><div class="list">${taskList(top)||empty('Ajoute une tâche avec une échéance pour construire ta journée.')}</div><div class="sectionhead"><h2>Habitudes prévues</h2><button class="textButton" onclick="go('habits')">Gérer →</button></div><div class="list">${habitList(habits)||empty('Aucune habitude prévue aujourd’hui.')}</div></section><aside><div class="sectionhead"><h2>Cette semaine</h2></div><div class="card summaryPanel"><p><strong>${week.tasks}</strong> tâches réalisées</p><p><strong>${week.minutes} min</strong> de concentration</p><p><strong>${week.habits===null?'—':week.habits+' %'}</strong> de régularité</p><button class="btn" onclick="openWeeklyReview()">Faire ma revue</button></div><div class="sectionhead"><h2>Objectif à suivre</h2></div>${S.goals.filter(g=>g.status==='active').sort((a,b)=>({high:0,medium:1,low:2}[a.priority]??1)-({high:0,medium:1,low:2}[b.priority]??1)).slice(0,1).map(goalCard).join('')||`<button class="card menuTile" onclick="openGoal()">${icon('goals')} Définir mon premier objectif</button>`}</aside></div>`;}
function taskList(arr,selectable=false){return arr.map(t=>`<article class="item taskRow ${t.status==='done'?'completed':''}">${selectable?`<label class="triageSelect"><input type="checkbox" aria-label="Sélectionner ${esc(t.title)}" ${selectedTaskIds.has(t.id)?'checked':''} onchange="toggleTaskSelection('${t.id}',this.checked)"></label>`:''}<button class="check ${t.status==='done'?'done':''}" aria-label="${t.status==='done'?'Rouvrir':'Terminer'} ${esc(t.title)}" onclick="toggleTask('${t.id}')">${t.status==='done'?'✓':''}</button><div class="grow"><button class="taskTitle" onclick="openTask('${t.id}')">${esc(t.title)}</button><div class="taskMeta"><span class="tag ${t.priority==='high'?'high':''}">${priorityName(t.priority)}</span>${t.due?`<span class="${t.due<iso()&&t.status!=='done'?'error':''}">${esc(t.due)} ${esc(t.dueTime||'')}</span>`:'<span>Sans date</span>'}${t.repeat&&t.repeat!=='none'?`<span>↻ ${repeatName(t.repeat)}</span>`:''}</div><small class="muted">${esc(projectName(t.projectId)||goalName(t.goalId)||'Action indépendante')} · prévu ${t.estimate||0} min · réalisé ${focusFor('task',t.id)} min</small>${t.subtasks?.length?`<details class="subtasks"><summary>${t.subtasks.filter(s=>s.done).length}/${t.subtasks.length} sous-tâches</summary>${t.subtasks.map(s=>`<label><input type="checkbox" ${s.done?'checked':''} onchange="toggleSubtask('${t.id}','${s.id}')"> ${esc(s.title)}</label>`).join('')}</details>`:''}</div><div class="miniActions">${iconButton('focus','Concentration',`openFocusFor('task','${t.id}')`)}${iconButton('edit','Modifier',`openTask('${t.id}')`)}${t.status!=='done'?`<button title="Reporter à demain" aria-label="Reporter à demain" onclick="postponeTask('${t.id}')">+1j</button>`:''}${iconButton('trash','Corbeille',`del('task','${t.id}')`)}</div></article>`).join('');}
function filteredTasks(){let a=S.tasks.filter(t=>(!taskFilters.q||[t.title,t.notes,goalName(t.goalId),projectName(t.projectId)].join(' ').toLocaleLowerCase().includes(taskFilters.q.toLocaleLowerCase()))&&(taskFilters.priority==='all'||t.priority===taskFilters.priority)&&(taskFilters.project==='all'||t.projectId===taskFilters.project));const f=taskFilters.status;if(f==='open')a=a.filter(t=>t.status!=='done');if(f==='today')a=a.filter(t=>t.due===iso());if(f==='late')a=a.filter(t=>t.due&&t.due<iso()&&t.status!=='done');if(['todo','doing','done'].includes(f))a=a.filter(t=>t.status===f);return taskFilters.sort==='priority'?rankedTasks(a):a.sort((a,b)=>taskFilters.sort==='title'?a.title.localeCompare(b.title):(a.due||'9999').localeCompare(b.due||'9999')||(a.dueTime||'99').localeCompare(b.dueTime||'99'));}
function renderTasks(){return `<div class="sectionhead"><div><div class="eyebrow">Exécuter</div><h2>Mes tâches</h2></div><button class="btn primary" onclick="openTask()">+ Nouvelle tâche</button></div><div class="card flat filters"><input aria-label="Rechercher une tâche" placeholder="Rechercher une tâche, un projet…" value="${esc(taskFilters.q)}" oninput="taskFilters.q=this.value;refreshTaskList(true)"><select aria-label="Statut" onchange="taskFilters.status=this.value;refreshTaskList(true)">${[['open','Ouvertes'],['all','Toutes'],['today','Aujourd’hui'],['late','En retard'],['todo','À faire'],['doing','En cours'],['done','Terminées']].map(([v,l])=>`<option value="${v}" ${taskFilters.status===v?'selected':''}>${l}</option>`).join('')}</select><select aria-label="Priorité" onchange="taskFilters.priority=this.value;refreshTaskList(true)">${[['all','Toutes priorités'],['high','Haute'],['medium','Normale'],['low','Basse']].map(([v,l])=>`<option value="${v}" ${taskFilters.priority===v?'selected':''}>${l}</option>`).join('')}</select><select aria-label="Projet" onchange="taskFilters.project=this.value;refreshTaskList(true)"><option value="all">Tous projets</option>${S.projects.map(p=>`<option value="${p.id}" ${taskFilters.project===p.id?'selected':''}>${esc(p.title)}</option>`).join('')}</select><select aria-label="Trier les tâches" onchange="taskFilters.sort=this.value;refreshTaskList(true)">${[['priority','Priorité'],['date','Échéance'],['title','Nom']].map(([v,l])=>`<option value="${v}" ${taskFilters.sort===v?'selected':''}>${l}</option>`).join('')}</select></div><section class="card triagePanel"><div class="triageHeading"><label class="checkLabel"><input id="selectVisibleTasks" type="checkbox" onchange="selectVisibleTasks(this.checked)"> Sélectionner les tâches affichées</label><strong id="selectedTaskCount">0 sélectionnée</strong></div><div class="triageActions" id="triageActions" hidden><div><label for="bulkTaskStatus">Statut</label><select id="bulkTaskStatus"><option value="">Conserver le statut</option><option value="todo">À faire</option><option value="doing">En cours</option><option value="done">Terminée</option></select><button class="btn" onclick="applyBulkTaskStatus()">Appliquer</button></div><div><label for="bulkTaskPriority">Priorité</label><select id="bulkTaskPriority"><option value="">Choisir…</option><option value="high">Haute</option><option value="medium">Normale</option><option value="low">Basse</option></select><button class="btn" onclick="applyBulkTaskPriority()">Appliquer</button></div><div><label for="bulkTaskDue">Échéance commune</label><input id="bulkTaskDue" type="date"><button class="btn" onclick="applyBulkTaskDue()">Planifier</button></div><div><label>Report</label><button class="btn" onclick="postponeSelectedTasks()">Reporter à demain</button></div></div><p class="muted triageHint">Sélectionne plusieurs tâches pour modifier leur statut, leur priorité ou leur échéance en une seule fois.</p></section><p class="muted" id="taskCount">${filteredTasks().length} tâche(s)</p><div class="list" id="taskbox">${taskList(filteredTasks(),true)||empty('Aucune tâche pour ces filtres.')}</div>`;}
function refreshTaskList(clearSelection=false){if(clearSelection)selectedTaskIds.clear();const a=filteredTasks();$('#taskbox').innerHTML=taskList(a,true)||empty('Aucun résultat');$('#taskCount').textContent=a.length+' tâche(s)';updateTaskTriage(a);}
function openTaskBasic(id='',preset={}){const t=S.tasks.find(x=>x.id===id)||{title:'',due:iso(),priority:'medium',status:'todo',estimate:25,goalId:'',projectId:'',notes:'',repeat:'none',dueTime:'',remind:false,subtasks:[],...preset};modal(id?'Modifier la tâche':'Nouvelle tâche',`<div class="formgrid"><div class="span2"><label>Titre *</label><input id="f_title" value="${esc(t.title)}" maxlength="300"></div><div><label>Date</label><input id="f_due" type="date" value="${t.due||''}"></div><div><label>Heure de début</label><input id="f_time" type="time" value="${t.dueTime||''}"></div><div><label>Priorité</label><select id="f_priority">${['high','medium','low'].map(v=>`<option value="${v}" ${v===t.priority?'selected':''}>${priorityName(v)}</option>`).join('')}</select></div><div><label>Statut</label><select id="f_status">${[['todo','À faire'],['doing','En cours'],['done','Terminée']].map(([v,l])=>`<option value="${v}" ${v===t.status?'selected':''}>${l}</option>`).join('')}</select></div><div><label>Objectif</label><select id="f_goal">${opts(S.goals,t.goalId)}</select></div><div><label>Projet</label><select id="f_project" onchange="taskProjectChanged()">${opts(S.projects,t.projectId)}</select></div><div><label>Durée estimée (min)</label><input id="f_est" type="number" min="0" max="1440" value="${t.estimate||0}"></div><div><label>Récurrence</label><select id="f_repeat">${['none','daily','weekdays','weekly','monthly'].map(v=>`<option value="${v}" ${v===t.repeat?'selected':''}>${repeatName(v)}</option>`).join('')}</select></div><div class="span2"><label class="checkLabel"><input type="checkbox" id="f_remind" ${t.remind?'checked':''}> Rappel à l’heure prévue (Android, après autorisation)</label><small class="muted">Une tâche récurrente crée sa prochaine occurrence quand tu la termines, sans rattraper toutes les dates manquées.</small></div><div class="span2"><label>Sous-tâches — une ligne par action</label><textarea id="f_subtasks" placeholder="Préparer les documents\nRelire le dossier">${esc((t.subtasks||[]).map(s=>s.title).join('\n'))}</textarea></div><div class="span2"><label>Notes</label><textarea id="f_notes">${esc(t.notes||'')}</textarea></div></div>`,`<button class="btn" onclick="closeModal()">Annuler</button><button class="btn primary" onclick="saveTask('${id}')">Enregistrer</button>`);taskProjectChanged();}
function taskProjectChanged(){updateTaskMilestones();const p=S.projects.find(p=>p.id===$('#f_project').value);$('#f_goal').disabled=!!p;if(p)$('#f_goal').value=p.goalId||'';}
function saveTask(id){const title=$('#f_title').value.trim(),estimate=Number($('#f_est').value),due=$('#f_due').value,repeat=$('#f_repeat').value,remind=$('#f_remind').checked,time=$('#f_time').value;if(!title)return toast('Le titre est obligatoire');if(!Number.isFinite(estimate)||estimate<0||estimate>1440)return toast('Durée entre 0 et 1 440 minutes');if(repeat!=='none'&&!due)return toast('Une date est requise pour la récurrence');if(remind&&(!due||!time))return toast('Choisis une date et une heure pour le rappel');if(!validLinks('#f_goal','#f_project'))return;const old=S.tasks.find(x=>x.id===id),status=$('#f_status').value;
 const lines=$('#f_subtasks').value.split('\n').map(x=>x.trim()).filter(Boolean);if(lines.length>100)return toast('Maximum 100 sous-tâches');const used=new Set();const subtasks=lines.map(title=>{const previous=old?.subtasks.find(x=>x.title===title&&!used.has(x.id));if(previous){used.add(previous.id);return previous;}return {id:uid(),title,done:false};});
 const t={...old,id:old?.id||uid(),title,due,dueTime:time,priority:$('#f_priority').value,status:old?.status||'todo',goalId:$('#f_goal').value,projectId:$('#f_project').value,milestoneId:$('#f_milestone')?.value||'',estimate,notes:$('#f_notes').value,repeat,remind,subtasks,createdAt:old?.createdAt||iso(),repeatDay:old?.due===due?old?.repeatDay:Number(due.slice(-2))||1};const i=S.tasks.findIndex(x=>x.id===id);i>=0?S.tasks[i]=t:S.tasks.push(t);closeModal();setTaskStatus(t.id,status);toast('Tâche enregistrée');}
function goalWizardBaseV6(g){let html=goalWizardV5(g);const domains=[...new Set([...(S.settings.domains||[]),g.area].filter(Boolean))];html=html.replace(/<select id="g_area">[\s\S]*?<\/select>/,`<select id="g_area">${domains.map(x=>`<option ${g.area===x?'selected':''}>${esc(x)}</option>`).join('')}</select>`);return html.replace('<h2>2. Mesure & échéance</h2>',`<h2>2. Mesure & échéance</h2><label>Calcul de progression</label><select id="g_progress" onchange="goalModeUI()">${[['manual','Valeur saisie manuellement'],['tasks','Pourcentage de tâches liées terminées'],['habits','Régularité des habitudes liées'],['focus','Minutes de concentration liées']].map(([v,l])=>`<option value="${v}" ${(g.progressMode||'manual')===v?'selected':''}>${l}</option>`).join('')}</select><div id="g_window_wrap"><label>Période des habitudes</label><select id="g_window">${[7,30,90].map(n=>`<option value="${n}" ${g.habitWindow===n?'selected':''}>${n} jours</option>`).join('')}</select></div><p class="muted" id="g_rule"></p>`);}
function openGoal(id=''){openGoalV5(id);goalModeUI();}
function goalModeUI(){const mode=$('#g_progress').value;$('#g_rule').textContent={manual:'La progression suit la valeur actuelle, y compris pour un objectif à la baisse.',tasks:'Chaque tâche liée compte de façon égale. Ajouter une tâche peut modifier le pourcentage.',habits:'Réalisations par rapport aux jours/sessions prévus sur la période choisie. La valeur peut baisser avec le temps.',focus:'La cible correspond au nombre total de minutes de concentration souhaitées.'}[mode];$('#g_window_wrap').hidden=mode!=='habits';for(const id of ['g_start','g_current'])$('#'+id).disabled=mode!=='manual';$('#g_target').disabled=['tasks','habits'].includes(mode);$('#g_unit').disabled=mode!=='manual';if(mode==='focus')$('#g_unit').value='min';}
function saveGoal(id){const title=$('#g_title').value.trim(),mode=$('#g_progress').value;if(!title){goalStep=0;showGoalStep();return toast('Décris ton objectif');}const start=Number($('#g_start').value),target=Number($('#g_target').value),value=Number($('#g_current').value);if(![start,target,value].every(Number.isFinite)||mode==='focus'&&target<=0)return toast('Mesures invalides ; la cible focus doit être positive');const old=S.goals.find(g=>g.id===id);const g={...old,id:id||uid(),title,area:$('#g_area').value,why:$('#g_why').value,deadline:$('#g_deadline').value,priority:$('#g_priority').value,start,target,current:value,unit:$('#g_unit').value,status:$('#g_status').value,obstacles:$('#g_obstacles').value,skills:$('#g_skills').value,support:$('#g_support').value,plan:$('#g_plan').value,daily:$('#g_daily').value,progressMode:mode,habitWindow:Number($('#g_window').value),history:old?.history||[],createdAt:old?.createdAt||iso()};const i=S.goals.findIndex(x=>x.id===id);i>=0?S.goals[i]=g:S.goals.push(g);save();closeModal();render();toast('Objectif enregistré');}
function goalCard(g){const p=pctGoal(g),ts=S.tasks.filter(t=>t.goalId===g.id);return `<article class="card goalcard"><div class="goalHeading"><span class="tag">${esc(g.area||'Personnel')}</span><strong>${p}%</strong></div><button class="goalTitle" onclick="goalDetails('${g.id}')">${esc(g.title)}</button><p class="muted caption">${g.deadline?'Échéance '+esc(g.deadline):'Sans échéance'} · ${{manual:'Mesure manuelle',tasks:'Tâches liées',habits:'Régularité',focus:'Minutes focus'}[g.progressMode]||'Mesure manuelle'}</p><div class="progress"><span style="width:${p}%"></span></div><div class="linked" style="margin:14px 0"><span>${ts.filter(t=>t.status==='done').length}/${ts.length} tâches</span><span>${S.habits.filter(h=>h.goalId===g.id).length} habitudes</span><span>${focusFor('goal',g.id)} min</span></div><div class="miniActions"><button onclick="goalDetails('${g.id}')">Plan d’action →</button>${iconButton('edit','Modifier l’objectif',`openGoal('${g.id}')`)}${iconButton('trash','Mettre à la corbeille',`del('goal','${g.id}')`)}</div></article>`;}
function goalDetails(id){const g=S.goals.find(g=>g.id===id);if(!g)return;modal(esc(g.title),`<div class="eyebrow">${esc(g.area)} · ${pctGoal(g)} %</div><p style="margin-top:12px">${esc(g.why||'Précise pourquoi cet objectif compte pour toi.')}</p><div class="chips"><button class="btn primary" onclick="openTask('',{goalId:'${id}'})">+ Action</button><button class="btn" onclick="openProject('',{goalId:'${id}'})">+ Projet</button><button class="btn" onclick="openHabit('',{goalId:'${id}'})">+ Habitude</button><button class="btn" onclick="openLinked('${id}')">Lier des éléments existants</button></div><h3 style="margin-top:24px">Transformer mon plan en actions</h3><p class="muted">Une ligne par tâche. Vérifie la liste avant la création.</p><textarea id="planLines">${esc(g.plan||'')}</textarea><button class="btn" style="margin-top:10px" onclick="createPlanTasks('${id}')">Créer les tâches de ce plan</button><h3 style="margin-top:24px">Actions liées</h3><div class="list">${taskList(S.tasks.filter(t=>t.goalId===id))||empty('Aucune action liée')}</div><h3 style="margin-top:24px">Historique de progression</h3>${goalHistoryChart(g)}<div class="grid g2" style="margin-top:20px"><div><h4>Obstacles</h4><p>${esc(g.obstacles||'—')}</p><h4>Compétences</h4><p>${esc(g.skills||'—')}</p></div><div><h4>Soutien</h4><p>${esc(g.support||'—')}</p><h4>Action régulière</h4><p>${esc(g.daily||'—')}</p></div></div>`,`<button class="btn" onclick="openGoal('${id}')">Modifier</button><button class="btn primary" onclick="closeModal()">Fermer</button>`,true);}
function goalHistoryChart(g){const rows=(g.history||[]).slice(-30);if(!rows.length)return empty('L’historique démarre avec tes premières modifications en V6.');return `<div class="historyRows">${rows.slice().reverse().map(x=>`<div><span>${esc(x.date)}</span><div class="progress"><span style="width:${x.value}%"></span></div><strong>${x.value}%</strong></div>`).join('')}</div>`;}
function createPlanTasks(gid){const lines=$('#planLines').value.split('\n').map(x=>x.trim().replace(/^[-*•]\s*/, '')).filter(Boolean);if(!lines.length)return toast('Ajoute au moins une action');if(lines.length>50)return toast('Maximum 50 actions par création');const titles=new Set(S.tasks.filter(t=>t.goalId===gid).map(t=>t.title.toLowerCase()));const fresh=lines.filter((x,i)=>!titles.has(x.toLowerCase())&&lines.findIndex(y=>y.toLowerCase()===x.toLowerCase())===i);if(!fresh.length)return toast('Ces actions sont déjà liées à cet objectif');if(!confirm(`Créer ${fresh.length} tâche(s) sans échéance ? Tu pourras les planifier ensuite.`))return;for(const title of fresh)S.tasks.push({id:uid(),title,goalId:gid,projectId:'',due:'',dueTime:'',priority:'medium',status:'todo',estimate:25,notes:'',repeat:'none',subtasks:[],createdAt:iso(),completedAt:null});save();goalDetails(gid);render();}
function openProject(id='',preset={}){const p=S.projects.find(x=>x.id===id)||{title:'',goalId:'',status:'active',deadline:'',notes:'',milestones:[],...preset};modal(id?'Modifier le projet':'Nouveau projet',`<div class="formgrid"><div class="span2"><label>Nom *</label><input id="p_title" value="${esc(p.title)}"></div><div><label>Objectif</label><select id="p_goal">${opts(S.goals,p.goalId)}</select></div><div><label>Échéance</label><input id="p_deadline" type="date" value="${p.deadline||''}"></div><div><label>Statut</label><select id="p_status">${[['active','Actif'],['paused','En pause'],['done','Terminé']].map(([v,l])=>`<option value="${v}" ${p.status===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="span2"><label>Notes</label><textarea id="p_notes">${esc(p.notes||'')}</textarea></div></div>`,`<button class="btn" onclick="closeModal()">Annuler</button><button class="btn primary" onclick="saveProject('${id}')">Enregistrer</button>`);}
function saveProject(id){const title=$('#p_title').value.trim();if(!title)return toast('Nom obligatoire');const old=S.projects.find(p=>p.id===id),p={...old,id:id||uid(),title,goalId:$('#p_goal').value,deadline:$('#p_deadline').value,status:$('#p_status').value,notes:$('#p_notes').value,milestones:old?.milestones||[]};const i=S.projects.findIndex(p=>p.id===id);i>=0?S.projects[i]=p:S.projects.push(p);reconcileLinks();save();closeModal();render();}
function renderProjectsBasic(){return `<div class="sectionhead"><div><div class="eyebrow">Structurer</div><h2>Projets & jalons</h2></div><button class="btn primary" onclick="openProject()">+ Nouveau projet</button></div><div class="grid g2">${S.projects.map(p=>{const ts=S.tasks.filter(t=>t.projectId===p.id),done=ts.filter(t=>t.status==='done').length;return `<article class="card"><span class="tag">${esc(goalName(p.goalId)||'Projet indépendant')}</span><button class="goalTitle" onclick="projectDetails('${p.id}')">${esc(p.title)}</button><p class="muted">${done}/${ts.length} tâches · ${p.milestones.filter(m=>m.done).length}/${p.milestones.length} jalons · ${focusFor('project',p.id)} min</p><div class="progress"><span style="width:${ts.length?done/ts.length*100:0}%"></span></div><div class="miniActions" style="margin-top:16px"><button onclick="projectDetails('${p.id}')">Ouvrir le projet →</button>${iconButton('edit','Modifier',`openProject('${p.id}')`)}${iconButton('trash','Corbeille',`del('project','${p.id}')`)}</div></article>`;}).join('')||empty('Crée un projet pour organiser plusieurs actions.')}</div>`;}
function projectDetailsBaseV6(id){const p=S.projects.find(p=>p.id===id);if(!p)return;modal(esc(p.title),`<p class="muted">${esc(goalName(p.goalId))} · ${p.deadline||'Sans échéance'}</p><p>${esc(p.notes||'')}</p><button class="btn primary" onclick="openTask('',{projectId:'${id}',goalId:'${p.goalId||''}'})">+ Tâche du projet</button><h3 style="margin-top:24px">Tableau d’avancement</h3><div class="kanban">${[['todo','À faire'],['doing','En cours'],['done','Terminé']].map(([v,l])=>`<section><h4>${l}</h4>${S.tasks.filter(t=>t.projectId===id&&t.status===v).map(t=>`<article class="kanbanCard"><button class="taskTitle" onclick="openTask('${t.id}')">${esc(t.title)}</button><small>${t.due||'Sans date'}</small><select aria-label="Statut de ${esc(t.title)}" onchange="setTaskStatus('${t.id}',this.value);projectDetails('${id}')">${[['todo','À faire'],['doing','En cours'],['done','Terminé']].map(([s,n])=>`<option value="${s}" ${s===v?'selected':''}>${n}</option>`).join('')}</select></article>`).join('')||'<p class="muted caption">Aucune tâche</p>'}</section>`).join('')}</div><h3 style="margin-top:24px">Jalons</h3><div class="list">${p.milestones.map(m=>`<div class="item"><button class="check ${m.done?'done':''}" onclick="toggleMilestone('${id}','${m.id}')">${m.done?'✓':''}</button><div class="grow"><b>${esc(m.title)}</b><small>${m.due||'Sans date'}</small></div><button class="btn" onclick="editMilestone('${id}','${m.id}')">Modifier</button></div>`).join('')||empty('Ajoute une étape importante pour matérialiser l’avancement.')}</div><button class="btn" style="margin-top:12px" onclick="editMilestone('${id}')">+ Jalon</button><h3 style="margin-top:24px">Habitudes associées</h3>${habitList(S.habits.filter(h=>h.projectId===id))||empty('Aucune habitude liée')}`,`<button class="btn" onclick="closeModal()">Fermer</button>`,true);}
function editMilestone(pid,mid=''){const m=S.projects.find(p=>p.id===pid)?.milestones.find(m=>m.id===mid)||{title:'',due:''};modal('Jalon',`<label>Titre *</label><input id="m_title" value="${esc(m.title)}"><label>Échéance</label><input id="m_due" type="date" value="${m.due||''}">`,`<button class="btn" onclick="projectDetails('${pid}')">Retour</button>${mid?`<button class="btn danger" onclick="deleteMilestone('${pid}','${mid}')">Supprimer</button>`:''}<button class="btn primary" onclick="saveMilestone('${pid}','${mid}')">Enregistrer</button>`);}
function saveMilestone(pid,mid){const p=S.projects.find(p=>p.id===pid),title=$('#m_title').value.trim();if(!title)return toast('Titre obligatoire');const old=p.milestones.find(m=>m.id===mid),m={id:mid||uid(),title,due:$('#m_due').value,done:old?.done||false};const i=p.milestones.findIndex(m=>m.id===mid);i>=0?p.milestones[i]=m:p.milestones.push(m);save();projectDetails(pid);}
function toggleMilestone(pid,mid){const m=S.projects.find(p=>p.id===pid)?.milestones.find(m=>m.id===mid);if(m){m.done=!m.done;save();projectDetails(pid);}}
function deleteMilestone(pid,mid){if(!confirm('Supprimer ce jalon ?'))return;const p=S.projects.find(p=>p.id===pid);p.milestones=p.milestones.filter(m=>m.id!==mid);save();projectDetails(pid);}

function openHabitBaseV6(id='',preset={}){const h=S.habits.find(h=>h.id===id)||{title:'',goalId:'',projectId:'',type:'check',target:1,unit:'session',freq:'daily',times:3,days:[],monthDays:[1],reminder:'',active:true,...preset};modal(id?'Modifier l’habitude':'Nouvelle habitude',`<div class="formgrid"><div class="span2"><label>Habitude *</label><input id="h_title" value="${esc(h.title)}"></div><div><label>Objectif</label><select id="h_goal">${opts(S.goals,h.goalId)}</select></div><div><label>Projet</label><select id="h_project" onchange="habitProjectChanged()">${opts(S.projects,h.projectId)}</select></div><div><label>Suivi</label><select id="h_type" onchange="habitTypeUI()">${[['check','Validation simple'],['timer','Durée / minuteur'],['count','Quantité'],['session','Nombre de sessions']].map(([v,l])=>`<option value="${v}" ${h.type===v?'selected':''}>${l}</option>`).join('')}</select></div><div><label>Fréquence</label><select id="h_freq" onchange="habitFreqUI()">${[['daily','Tous les jours'],['weekdays','Lundi à vendredi'],['days','Jours choisis'],['weekly','X jours réussis / semaine'],['monthly','Dates du mois']].map(([v,l])=>`<option value="${v}" ${h.freq===v?'selected':''}>${l}</option>`).join('')}</select></div><div><label>Cible de la journée</label><input id="h_target" type="number" min="1" step="any" value="${h.target}"></div><div><label>Unité</label><input id="h_unit" value="${esc(h.unit)}"></div><div id="weeklyFields"><label>Jours réussis attendus / semaine</label><input id="h_times" type="number" min="1" max="7" value="${h.times}"></div><div><label>Heure du rappel Android</label><input id="h_reminder" type="time" value="${h.reminder||''}"></div><div class="span2" id="weekdayFields"><label>Jours programmés</label><div class="chips">${['Dim','Lun','Mar','Mer','Jeu','Ven','Sam'].map((x,i)=>`<label class="chip checkLabel"><input type="checkbox" name="hday" value="${i}" ${h.days.includes(i)?'checked':''}>${x}</label>`).join('')}</div></div><div class="span2" id="monthlyFields"><label>Dates séparées par des virgules (1–31)</label><input id="h_monthdays" value="${(h.monthDays||[1]).join(', ')}"><small class="muted">Le 31 est ignoré dans un mois sans 31. La cible reste une cible par journée.</small></div><div class="span2"><p class="muted">Le rappel nécessite l’autorisation dans Paramètres. Pour X jours/semaine, le rappel est quotidien ; tu choisis les jours où atteindre la cible.</p></div></div>`,`<button class="btn" onclick="closeModal()">Annuler</button><button class="btn primary" onclick="saveHabit('${id}')">Enregistrer</button>`);habitFreqUI();habitProjectChanged();}
function habitProjectChanged(){const p=S.projects.find(p=>p.id===$('#h_project').value);$('#h_goal').disabled=!!p;if(p)$('#h_goal').value=p.goalId||'';}
function habitFreqUI(){const f=$('#h_freq').value;$('#weeklyFields').hidden=f!=='weekly';$('#weekdayFields').hidden=f!=='days';$('#monthlyFields').hidden=f!=='monthly';}
function habitTypeUI(){const t=$('#h_type').value;$('#h_unit').value=t==='timer'?'min':t==='count'?'unité':'session';if(t==='check')$('#h_target').value=1;}
function saveHabitBaseV6(id){const title=$('#h_title').value.trim(),target=Number($('#h_target').value),times=Number($('#h_times').value),freq=$('#h_freq').value,days=Array.from(document.querySelectorAll('input[name=hday]:checked')||[]).map(x=>+x.value),monthDays=[...new Set(String($('#h_monthdays')?.value||'1').split(',').map(x=>Number(x.trim())))].sort((a,b)=>a-b);if(!title)return toast('Nom obligatoire');if(!Number.isFinite(target)||target<=0||!Number.isInteger(times)||times<1||times>7)return toast('Cible positive et fréquence entre 1 et 7 requises');if(freq==='days'&&!days.length)return toast('Choisis au moins un jour');if(freq==='monthly'&&(!monthDays.length||monthDays.some(d=>!Number.isInteger(d)||d<1||d>31)))return toast('Les dates doivent être entre 1 et 31');if(!validLinks('#h_goal','#h_project'))return;const old=S.habits.find(h=>h.id===id),type=$('#h_type').value;const h={...old,id:id||uid(),title,goalId:$('#h_goal').value,projectId:$('#h_project').value,type,target:type==='check'?1:target,unit:type==='timer'?'min':$('#h_unit').value,freq,times,days,monthDays:freq==='monthly'?monthDays:(old?.monthDays||[1]),reminder:$('#h_reminder').value,active:old?.active??true,createdAt:old?.createdAt||iso(),pauses:old?.pauses||[]};const i=S.habits.findIndex(h=>h.id===id);i>=0?S.habits[i]=h:S.habits.push(h);save();closeModal();render();}
function freqText(h){return h.freq==='monthly'?'Les '+h.monthDays.join(', ')+' du mois':h.freq==='days'?h.days.map(d=>['Dim','Lun','Mar','Mer','Jeu','Ven','Sam'][d]).join(', '):h.freq==='weekly'?h.times+' jours réussis / semaine':h.freq==='weekdays'?'Lundi à vendredi':'Tous les jours';}
function streak(id){const h=S.habits.find(h=>h.id===id);if(!h)return 0;let count=0;if(h.freq==='weekly'){let [start]=bounds('week',iso());for(let i=0;i<104;i++){const [a,b]=bounds('week',start),days=datesBetween(a,b).filter(d=>scheduled(h,d)),n=days.filter(d=>d<=iso()&&habitDone(id,d)).length;if(days.length&&n>=Math.min(h.times,days.length))count++;else if(days.length&&i>0)break;const d=new Date(a+'T12:00:00');d.setDate(d.getDate()-7);start=iso(d);}return count;}for(let i=0;i<730;i++){const d=new Date();d.setDate(d.getDate()-i);const day=iso(d);if(!scheduled(h,day))continue;if(habitDone(id,day))count++;else if(i>0)break;}return count;}
function habitList(arr){return arr.map(h=>{const planned=scheduled(h,iso()),paused=pausedOn(h,iso())||!h.active;return `<article class="item habitrow"><div><b>${esc(h.title)}</b><small class="muted">${freqText(h)} · ${habitValue(h.id,iso())}/${h.type==='check'?1:h.target} ${esc(h.type==='timer'?'min':h.unit)}</small><div class="weekdots">${last7().map(d=>`<button class="daydot ${habitDone(h.id,d)?'done':scheduled(h,d)?'':'unplanned'}" title="${d} : ${habitValue(h.id,d)}" aria-label="Réalisation du ${d}" onclick="logHabit('${h.id}');$('#log_date').value='${d}';$('#log_value').value=habitValue('${h.id}','${d}')">${habitDone(h.id,d)?'✓':scheduled(h,d)?new Date(d+'T12:00').toLocaleDateString('fr',{weekday:'narrow'}):'—'}</button>`).join('')}</div>${paused?'<span class="tag">En pause</span>':!planned?'<span class="tag">Non prévue aujourd’hui</span>':''}</div><div class="miniActions">${h.type==='timer'?iconButton('focus','Démarrer le minuteur',`habitTimer('${h.id}')`):''}<button onclick="logHabit('${h.id}')">Saisir</button>${iconButton('edit','Modifier',`openHabit('${h.id}')`)}<button onclick="toggleHabitPause('${h.id}')">${paused?'Reprendre':'Pause'}</button>${iconButton('trash','Corbeille',`del('habit','${h.id}')`)}</div></article>`;}).join('');}
function renderHabits(){return `<div class="sectionhead"><div><div class="eyebrow">Répéter avec intention</div><h2>Mes habitudes</h2></div><button class="btn primary" onclick="openHabit()">+ Nouvelle habitude</button></div><div class="list">${S.habits.map(h=>{const p=habitPeriod(h,lastN(30)[0],iso());return `<div class="card">${habitList([h])}<div class="linked" style="margin-top:12px"><span>Série : ${streak(h.id)} ${h.freq==='weekly'?'semaines':'jours prévus'}</span><span>30 jours : ${p.done}/${p.expected} réalisations attendues</span><span>${focusFor('habit',h.id)} min focus</span></div></div>`;}).join('')||empty('Commence par une petite habitude facile à répéter.')}</div>`;}
function calendarTasks(d){return S.tasks.filter(t=>t.due===d).sort((a,b)=>(a.dueTime||'99').localeCompare(b.dueTime||'99'));}
function renderPlanner(){return `<div class="sectionhead"><div><div class="eyebrow">Donner une place à tes actions</div><h2>Calendrier</h2></div><button class="btn primary" onclick="openTask('',{due:selectedDay})">+ Planifier</button></div><div class="calendarToolbar"><div class="chips">${[['day','Jour'],['week','Semaine'],['month','Mois'],['quarter','Trimestre'],['year','Année']].map(([v,l])=>`<button class="chip ${S.period===v?'active':''}" onclick="setPeriod('${v}')">${l}</button>`).join('')}</div><div class="chips"><button class="btn" aria-label="Période précédente" onclick="movePeriod(-1)">←</button><input aria-label="Date de référence" type="date" value="${plannerDate}" onchange="if(this.value){plannerDate=this.value;selectedDay=this.value;render()}"><button class="btn" aria-label="Période suivante" onclick="movePeriod(1)">→</button><button class="btn" onclick="plannerDate=iso();selectedDay=iso();render()">Aujourd’hui</button></div></div>${['quarter','year'].includes(S.period)?periodView():S.period==='month'?monthCalendar():S.period==='week'?weekCalendar():dayAgenda(plannerDate)}`;}
function monthCalendar(){const [a,b]=bounds('month',plannerDate),first=bounds('week',a)[0],last=bounds('week',b)[1];const dates=datesBetween(first,last);return `<div class="card calendarCard"><h3>${new Date(a+'T12:00').toLocaleDateString('fr-FR',{month:'long',year:'numeric'})}</h3><div class="monthLabels">${['Lun','Mar','Mer','Jeu','Ven','Sam','Dim'].map(x=>`<b>${x}</b>`).join('')}</div><div class="monthGrid">${dates.map(d=>{const ts=calendarTasks(d);return `<div class="calendarCell ${d<a||d>b?'otherMonth':''} ${d===iso()?'isToday':''} ${d===selectedDay?'selected':''}" ondragover="event.preventDefault()" ondrop="dropTask(event,'${d}')"><button class="dayHeader" aria-label="Voir le ${d}" onclick="selectedDay='${d}';render()">${Number(d.slice(-2))}<span>${ts.length?ts.length+' tâche'+(ts.length>1?'s':''):''}</span></button><div class="cellEvents">${ts.slice(0,3).map(t=>`<button class="calendarEvent ${t.status==='done'?'completed':''}" draggable="true" ondragstart="event.dataTransfer.setData('text/plain','${t.id}')" onclick="openTask('${t.id}')">${esc(t.dueTime||'')} ${esc(t.title)}</button>`).join('')}${ts.length>3?`<button class="textButton" onclick="selectedDay='${d}';render()">+${ts.length-3}</button>`:''}</div></div>`;}).join('')}</div><p class="muted caption">Clique sur une date pour le détail. Sur PC, déplace une tâche vers un autre jour ; sur mobile, modifie sa date depuis sa fiche.</p></div>${dayAgenda(selectedDay)}`;}
function weekCalendar(){const [a,b]=bounds('week',plannerDate);return `<div class="weekGrid">${datesBetween(a,b).map(d=>`<section class="card weekDay ${d===iso()?'isToday':''}" ondragover="event.preventDefault()" ondrop="dropTask(event,'${d}')"><button class="dayHeader" onclick="selectedDay='${d}';S.period='day';plannerDate='${d}';render()">${new Date(d+'T12:00').toLocaleDateString('fr-FR',{weekday:'short',day:'numeric'})}</button>${calendarTasks(d).map(t=>`<button class="calendarEvent" draggable="true" ondragstart="event.dataTransfer.setData('text/plain','${t.id}')" onclick="openTask('${t.id}')"><b>${t.dueTime||'Sans heure'}</b><span>${esc(t.title)}</span><small>${t.estimate||0} min</small></button>`).join('')||'<p class="muted caption">Libre</p>'}<button class="textButton" onclick="openTask('',{due:'${d}'})">+ Ajouter</button></section>`).join('')}</div>`;}
function dayAgenda(d){const ts=calendarTasks(d),hs=S.habits.filter(h=>scheduled(h,d));return `<div class="sectionhead"><h2>${new Date(d+'T12:00').toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long'})}</h2><button class="btn" onclick="openTask('',{due:'${d}'})">+ Action</button></div><div class="grid g2"><section class="card"><h3>Créneaux & actions</h3><div class="list">${ts.map(t=>`<div class="agendaLine"><div class="agendaTime">${t.dueTime||'—'}<small>${t.estimate||0} min</small></div><div class="grow">${taskList([t])}</div></div>`).join('')||empty('Cette journée est libre.')}</div></section><section class="card"><h3>Routines prévues</h3>${hs.map(h=>`<div class="item"><span>${esc(h.reminder||'—')}</span><div class="grow"><b>${esc(h.title)}</b><small>${h.target} ${esc(h.unit)}</small></div></div>`).join('')||empty('Aucune routine prévue')}<h3 style="margin-top:24px">Échéances</h3>${S.goals.filter(g=>g.deadline===d).map(g=>`<button class="btn" onclick="goalDetails('${g.id}')">${esc(g.title)}</button>`).join('')}${S.projects.flatMap(p=>p.milestones.filter(m=>m.due===d).map(m=>`<button class="btn" onclick="projectDetails('${p.id}')">${esc(m.title)} · ${esc(p.title)}</button>`)).join('')||'<p class="muted caption">Les échéances des objectifs et jalons apparaissent ici.</p>'}</section></div>`;}
function dropTask(e,d){e.preventDefault();const id=e.dataTransfer.getData('text/plain'),t=S.tasks.find(t=>t.id===id);if(!t)return;t.due=d;save();render();toast('Tâche déplacée au '+d);}
function renderStats(){const dates=lastN(statsDays),a=dates[0],b=iso(),pd=new Date(a+'T12:00');pd.setDate(pd.getDate()-1);const prevEnd=iso(pd);pd.setDate(pd.getDate()-statsDays+1);const cur=summaryPeriod(a,b),prev=summaryPeriod(iso(pd),prevEnd),delta=(x,y,unit='')=>`${x-y>0?'+':''}${x-y}${unit} vs période précédente`;return `<div class="sectionhead"><div><div class="eyebrow">Observer pour ajuster</div><h2>Statistiques</h2></div><div class="chips">${[7,30,90].map(n=>`<button class="chip ${statsDays===n?'active':''}" onclick="statsDays=${n};render()">${n} jours</button>`).join('')}</div></div><p class="muted">Du ${a} au ${b}. Comparaison avec les ${statsDays} jours précédents.</p><div class="grid g3"><div class="card kpi"><small>Tâches réalisées</small><strong>${cur.tasks}</strong><small>${delta(cur.tasks,prev.tasks)}</small></div><div class="card kpi"><small>Concentration</small><strong>${cur.minutes} min</strong><small>${delta(cur.minutes,prev.minutes,' min')}</small></div><div class="card kpi"><small>Régularité des habitudes</small><strong>${cur.habits===null?'—':cur.habits+' %'}</strong><small>${cur.habitDone}/${cur.habitExpected} réalisations attendues</small></div></div><p class="muted caption">${S.tasks.filter(t=>t.status==='done'&&!t.completedAt).length} ancienne(s) tâche(s) terminée(s) sans date de réalisation sont exclues des comparaisons. Pour X jours/semaine, le nombre attendu est plafonné aux jours programmés présents dans la période.</p><div class="grid g2" style="margin-top:18px"><section class="card"><h3>Concentration par jour</h3>${focusChart(dates)}<small class="muted">Sélectionne un jour pour retrouver les sessions.</small></section><section class="card"><h3>Estimation & temps réalisé</h3><div class="compareBars"><p>Prévu pour les tâches réalisées <strong>${cur.estimated} min</strong></p><div class="progress"><span style="width:${cur.estimated/Math.max(1,cur.estimated,cur.actualForTasks)*100}%"></span></div><p>Focus enregistré sur ces tâches <strong>${cur.actualForTasks} min</strong></p><div class="progress"><span style="width:${cur.actualForTasks/Math.max(1,cur.estimated,cur.actualForTasks)*100}%"></span></div></div><p class="muted caption">Temps focus cumulé de ces tâches, y compris les sessions antérieures à la période. Le travail non chronométré n’est pas mesuré.</p><button class="btn" onclick="openWeeklyReview()">Faire le point sur ma semaine</button></section></div><section class="card" style="margin-top:18px"><h3>Régularité par habitude</h3>${S.habits.map(h=>{const p=habitPeriod(h,a,b);return `<div class="habitStat"><div><b>${esc(h.title)}</b><small>${p.done}/${p.expected} · ${freqText(h)}</small></div><strong>${p.expected?Math.round(p.done/p.expected*100)+'%':'—'}</strong><div class="heat">${dates.slice(-30).map(d=>`<button class="daydot ${habitDone(h.id,d)?'done':scheduled(h,d)?'':'unplanned'}" aria-label="${d} : ${habitValue(h.id,d)}" title="${d} : ${habitValue(h.id,d)}" onclick="logHabit('${h.id}');$('#log_date').value='${d}';$('#log_value').value=habitValue('${h.id}','${d}')">${habitDone(h.id,d)?'✓':scheduled(h,d)?'·':'—'}</button>`).join('')}</div></div>`;}).join('')||empty('Aucune habitude')}</section><div class="sectionhead"><h2>Objectifs · situation actuelle</h2></div><div class="grid g2">${S.goals.map(goalCard).join('')||empty('Aucun objectif')}</div>`;}
function focusChart(dates){const vals=dates.map(d=>S.focus.filter(f=>f.date===d).reduce((n,f)=>n+f.minutes,0)),max=Math.max(1,...vals);return `<div class="focusChart" role="group" aria-label="Minutes de concentration par jour">${vals.map((v,i)=>`<button class="focusColumn" title="${dates[i]} : ${Math.round(v)} min" aria-label="${dates[i]} : ${Math.round(v)} minutes" onclick="showFocusDay('${dates[i]}')"><span class="columnValue">${dates.length<=7?Math.round(v):''}</span><i style="height:${Math.max(2,v/max*130)}px"></i><small>${dates.length<=7?dates[i].slice(8):i%Math.ceil(dates.length/6)===0?dates[i].slice(5):''}</small></button>`).join('')}</div>`;}
function renderJournal(){const j=S.journal.find(j=>j.date===journalDate),q=journalSearch.toLowerCase(),rows=S.journal.filter(j=>[j.text,j.tags,j.mood].join(' ').toLowerCase().includes(q)).sort((a,b)=>b.date.localeCompare(a.date));return `<div class="sectionhead"><div><div class="eyebrow">Apprendre de tes journées</div><h2>Journal & revues</h2></div><button class="btn" onclick="openWeeklyReview()">Revue hebdomadaire</button></div><div class="grid g2"><section class="card"><label>Date de l’entrée</label><input id="journalDate" type="date" value="${journalDate}" max="${iso()}" onchange="if(this.value){journalDate=this.value;render()}"><label style="margin-top:14px">Humeur</label><select id="mood">${['😊 Très bien','🙂 Bien','😐 Neutre','😕 Difficile'].map(x=>`<option ${j?.mood===x?'selected':''}>${x}</option>`).join('')}</select><label style="margin-top:14px">Ce que je retiens</label><textarea id="journalText" rows="8" placeholder="Une réussite, une difficulté, une chose à ajuster…">${esc(j?.text||'')}</textarea><label>Tags (séparés par des virgules)</label><input id="journalTags" value="${esc(j?.tags||'')}" placeholder="travail, famille, énergie"><div class="chips" style="margin-top:14px"><button class="btn primary" onclick="saveJournal()">Enregistrer</button>${j?`<button class="btn danger" onclick="del('journal','${j.date}')">Corbeille</button>`:''}</div></section><section class="card"><h3>Mes entrées</h3><input aria-label="Rechercher dans le journal" placeholder="Rechercher un mot ou un tag" value="${esc(journalSearch)}" oninput="journalSearch=this.value;refreshJournalList()"><div class="list" id="journalEntries" style="margin-top:16px">${journalRows(rows)}</div></section></div>`;}
function journalRows(rows){return rows.map(j=>`<button class="journalEntry ${j.date===journalDate?'selected':''}" onclick="journalDate='${j.date}';render()"><b>${esc(j.date)} · ${esc(j.mood)}</b><p>${esc(j.text.slice(0,180))}${j.text.length>180?'…':''}</p><small>${esc(j.tags||'')}</small></button>`).join('')||empty('Aucune entrée correspondante');}
function refreshJournalList(){const q=journalSearch.toLowerCase();$('#journalEntries').innerHTML=journalRows(S.journal.filter(j=>[j.text,j.tags,j.mood].join(' ').toLowerCase().includes(q)).sort((a,b)=>b.date.localeCompare(a.date)));}
function saveJournal(){const text=$('#journalText').value.trim();if(!text)return toast('Écris quelques mots avant d’enregistrer');const o={date:journalDate,text,mood:$('#mood').value,tags:$('#journalTags').value.trim()},i=S.journal.findIndex(j=>j.date===journalDate);i>=0?S.journal[i]=o:S.journal.push(o);save();render();toast('Entrée enregistrée');}
function openWeeklyReview(week=bounds('week',iso())[0]){const [a,b]=bounds('week',week),r=S.reviews.find(r=>r.week===a),s=summaryPeriod(a,b);modal('Revue de la semaine',`<div class="chips"><button class="btn" onclick="shiftReview('${a}',-7)">← Semaine précédente</button><button class="btn" onclick="shiftReview('${a}',7)">Semaine suivante →</button></div><p class="muted" style="margin-top:14px">${a} → ${b} · ${s.tasks} tâches réalisées · ${s.minutes} min focus</p><label>Mes réussites</label><textarea id="reviewWins">${esc(r?.wins||'')}</textarea><label>Mes difficultés et leçons</label><textarea id="reviewLessons">${esc(r?.lessons||'')}</textarea><label>Mes 3 résultats prioritaires pour la suite</label><textarea id="reviewNext">${esc(r?.next||'')}</textarea>`,`<button class="btn" onclick="closeModal()">Fermer</button><button class="btn primary" onclick="saveReview('${a}')">Enregistrer la revue</button>`);}
function shiftReview(d,n){const date=new Date(d+'T12:00');date.setDate(date.getDate()+n);openWeeklyReview(iso(date));}
function saveReview(week){const r={week,wins:$('#reviewWins').value,lessons:$('#reviewLessons').value,next:$('#reviewNext').value},i=S.reviews.findIndex(r=>r.week===week);i>=0?S.reviews[i]=r:S.reviews.push(r);save();closeModal();toast('Revue enregistrée');}
function coachInsights(){const out=[],late=todayTasks().filter(t=>t.due<iso());if(late.length)out.push({title:`${late.length} tâche(s) en retard`,text:`Commence par « ${late[0].title} », ou donne-lui une nouvelle date réaliste.`,action:`openTask('${late[0].id}')`,label:'Revoir cette tâche'});const orphan=S.goals.find(g=>g.status==='active'&&!S.tasks.some(t=>t.goalId===g.id)&&!S.habits.some(h=>h.goalId===g.id));if(orphan)out.push({title:'Un objectif attend son plan',text:`« ${orphan.title} » n’a encore aucune action ni habitude liée.`,action:`goalDetails('${orphan.id}')`,label:'Construire le plan'});const heavy=S.tasks.filter(t=>t.due===iso()&&t.status!=='done').reduce((n,t)=>n+(t.estimate||0),0);if(heavy>360)out.push({title:'Une journée chargée',text:`${heavy} minutes prévues, soit plus de 6 heures de tâches. Réserve du temps pour les imprévus.`,action:"go('planner')",label:'Réorganiser'});const weak=S.habits.find(h=>{const p=habitPeriod(h,lastN(7)[0],iso());return p.expected>=3&&p.done/p.expected<.5;});if(weak)out.push({title:'Réduire la difficulté',text:`« ${weak.title} » a moins de 50 % de réalisations sur les 7 derniers jours. Essaie une cible plus petite.`,action:`openHabit('${weak.id}')`,label:'Ajuster l’habitude'});const a=todayTasks()[0];if(a)out.push({title:'Prochaine action concrète',text:`Une session de ${S.settings.focus} min sur « ${a.title} » ferait avancer ta journée.`,action:`openFocusFor('task','${a.id}')`,label:'Commencer'});if(!out.length)out.push({title:'Préparer la suite',text:'Prends quelques minutes pour relire tes objectifs et noter une prochaine action.',action:'openWeeklyReview()',label:'Faire ma revue'});return out;}
function renderCoach(){return `<div class="pageIntro"><div class="eyebrow">Des conseils issus de tes données</div><h2>Mon bilan & mes prochaines actions</h2><p class="muted">Analyse locale à règles explicites. Tes informations restent sur l’appareil ; aucun service d’IA externe n’est appelé.</p></div><div class="grid g2">${coachInsights().map(i=>`<article class="card coach"><h3>${esc(i.title)}</h3><p>${esc(i.text)}</p><button class="btn primary" onclick="${i.action}">${i.label}</button></article>`).join('')}</div><div class="card" style="margin-top:20px"><h3>Un rendez-vous avec toi-même</h3><p class="muted">La revue permet de conserver tes réussites, tes obstacles et tes priorités de la semaine suivante.</p><button class="btn" onclick="openWeeklyReview()">Ouvrir ma revue</button></div>`;}

function movePeriod(n){const [a,b]=bounds(S.period,plannerDate),d=new Date((n>0?b:a)+'T12:00:00');d.setDate(d.getDate()+n);plannerDate=iso(d);selectedDay=plannerDate;render();}

// Native reminders, focus cycles and user preferences.
let reminderDebounce=null,reminderStatus='Non activés',reminderBusy=false,reminderAgain=false;
const notificationsNative=(method,args={})=>window.Capacitor.nativePromise('LocalNotifications',method,args);
function notificationId(str){let h=2166136261;for(let i=0;i<str.length;i++)h=Math.imul(h^str.charCodeAt(i),16777619);return (h>>>0)%2000000000+1000;}
function buildReminders(now=Date.now()){const rows=[];for(const t of S.tasks){if(!t.remind||t.status==='done'||!t.due||!t.dueTime)continue;const at=new Date(t.due+'T'+t.dueTime+':00').getTime();if(at>now)rows.push({id:notificationId('task'+t.id),title:'LifeOS · Action prévue',body:t.title,schedule:{at:new Date(at).toISOString(),allowWhileIdle:true},extra:{type:'task',id:t.id},channelId:'lifeos-reminders'});}
 for(const h of S.habits){if(!h.reminder||!h.active||pausedOn(h,iso()))continue;const [hour,minute]=h.reminder.split(':').map(Number);const days=h.freq==='weekdays'?[1,2,3,4,5]:h.freq==='days'?h.days:null;const base={title:'LifeOS · Ma routine',body:h.title,extra:{type:'habit',id:h.id},channelId:'lifeos-reminders'};
 if(h.freq==='monthly'){const start=new Date(now);for(let offset=0;offset<12;offset++)for(const d of h.monthDays){const date=new Date(start.getFullYear(),start.getMonth()+offset,d,hour,minute);if(date.getDate()===d&&date.getTime()>now)rows.push({...base,id:notificationId('habit'+h.id+iso(date)),schedule:{at:date.toISOString(),allowWhileIdle:true}});}}else if(days){for(const day of days)rows.push({...base,id:notificationId('habit'+h.id+'w'+day),schedule:{on:{weekday:day+1,hour,minute,second:0},repeats:true,allowWhileIdle:true}});}else rows.push({...base,id:notificationId('habit'+h.id),schedule:{on:{hour,minute,second:0},repeats:true,allowWhileIdle:true}});
 }return rows;
}
async function enableReminders(enabled){if(!isNative()){toast('Les rappels en arrière-plan nécessitent l’APK Android.');return;}try{if(enabled){const p=await notificationsNative('requestPermissions');if(p.display!=='granted')return alert('Autorisation de notifications refusée. Tu peux l’activer dans les réglages Android.');await notificationsNative('createChannel',{id:'lifeos-reminders',name:'Rappels LifeOS',importance:4,visibility:0,vibration:true});}S.settings.notifications=enabled;save();await syncReminders();render();}catch(e){alert('Rappels non activés : '+e.message);}}
async function syncReminders(){if(!isNative())return;if(reminderBusy){reminderAgain=true;return;}reminderBusy=true;try{const {display}=await notificationsNative('checkPermissions');if(display!=='granted'){reminderStatus='Autorisation Android nécessaire';return;}const pending=await notificationsNative('getPending');if(!S.settings.notifications){const old=(pending.notifications||[]).filter(n=>n.id!==900000001);if(old.length)await notificationsNative('cancel',{notifications:old.map(n=>({id:n.id}))});reminderStatus='Désactivés';return;}const notifications=buildReminders();if(notifications.length>400)throw Error('Plus de 400 rappels : réduis le nombre de tâches avec rappel.');const old=(pending.notifications||[]).filter(n=>n.id!==900000001);if(old.length)await notificationsNative('cancel',{notifications:old.map(n=>({id:n.id}))});if(notifications.length)await notificationsNative('schedule',{notifications});reminderStatus=notifications.length+' rappel(s) programmé(s)';}catch(e){reminderStatus='Rappels non programmés : '+e.message;}finally{reminderBusy=false;if(reminderAgain){reminderAgain=false;setTimeout(()=>syncReminders(),300);}if(current==='settings')render();}}
async function syncFocusAlarm(){if(!isNative())return;try{await notificationsNative('cancel',{notifications:[{id:900000001}]});if(S.settings.notifications&&focusSession?.running&&focusSession.end>Date.now())await notificationsNative('schedule',{notifications:[{id:900000001,title:'LifeOS · Minuteur terminé',body:focusSession.mode==='work'?'Ta session est terminée. Ouvre LifeOS pour faire le point.':'Ta pause est terminée.',channelId:'lifeos-reminders',schedule:{at:new Date(focusSession.end).toISOString(),allowWhileIdle:true},extra:{type:'focus'}}]});}catch(e){reminderStatus='Alerte minuteur indisponible : '+e.message;}}
async function exactAlarmSettings(){if(!isNative())return;try{await notificationsNative('changeExactNotificationSetting');}catch(e){alert(e.message);}}
function finishTone(){try{audioCtx??=new (window.AudioContext||window.webkitAudioContext)();audioCtx.resume();const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.frequency.value=660;gain.gain.setValueAtTime(.08,audioCtx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.6);osc.connect(gain).connect(audioCtx.destination);osc.start();osc.stop(audioCtx.currentTime+.65);}catch{}}
function focusDuration(mode){return (mode==='long'?S.settings.long:mode==='break'?S.settings.break:S.settings.focus)*60;}
function renderFocus(){const mode=focusSession?.mode||focusMode,label={work:'Concentration',break:'Pause courte',long:'Pause longue'}[mode]||'Concentration';return `<div class="sectionhead"><div><div class="eyebrow">Un temps pour avancer</div><h2>Focus Studio</h2></div><span class="tag">${S.settings.completedFocusCount||0} sessions complètes</span></div><div class="grid g2"><section class="card focusPanel"><div class="chips modeChoices">${[['work','Concentration'],['break','Pause'],['long','Pause longue']].map(([v,l])=>`<button class="chip ${mode===v?'active':''}" onclick="chooseFocusMode('${v}')">${l}</button>`).join('')}</div><p class="muted">${label}</p><div class="timer" id="focusClock">${fmt(focusRemain)}</div><div class="chips" style="justify-content:center"><button class="btn primary" id="focusBtn" onclick="toggleFocus()">${focusRunning?'Mettre en pause':focusSession?'Reprendre':'Démarrer'}</button><button class="btn" onclick="finishPartialFocus()" ${!focusSession?'disabled':''}>${mode==='work'?'Terminer & enregistrer':'Terminer la pause'}</button><button class="btn" onclick="resetFocus()">Réinitialiser</button></div><label style="margin-top:24px">Associer la session</label><select id="focusLink" ${focusSession?'disabled':''} onchange="focusSelection=this.value">${focusOptions()}</select><div class="focusOptions"><label class="checkLabel"><input type="checkbox" ${S.settings.autoCycles?'checked':''} onchange="S.settings.autoCycles=this.checked;save()"> Enchaîner automatiquement les phases tant que l’application reste active</label><small class="muted">Pause longue de ${S.settings.long} min après ${S.settings.cycles} sessions complètes. Au retour après une suspension, la phase suivante attend ton action.</small></div><h3 style="margin-top:24px">Ambiance</h3><div class="soundbar">${[['none','Silence'],['rain','Pluie synthétique'],['brown','Bruit doux'],['forest','Souffle forêt'],['custom','Mon fichier audio']].map(([v,l])=>`<button class="btn ${S.settings.sound===v?'active':''}" onclick="${v==='custom'?'chooseAudio()':`setSound('${v}')`}">${l}</button>`).join('')}</div><p class="muted caption">Tu peux utiliser ton propre enregistrement de pluie ou de nature. Le fichier reste sur l’appareil et doit être rechoisi après fermeture.</p><label>Volume</label><input type="range" min="0" max="1" step=".05" value="${S.settings.volume}" oninput="setVolume(this.value)"><button class="textButton" onclick="openTimerSettings()">Régler les cycles et durées →</button></section><section class="card"><h3>Historique des sessions</h3><div class="list">${S.focus.slice().reverse().slice(0,40).map(f=>`<div class="item"><div class="grow"><b>${Math.round(f.minutes*10)/10} min · ${esc(f.label)}</b><small>${esc(f.date)} · ${f.partial?'Session écourtée':'Session complète'}</small></div></div>`).join('')||empty('Démarre ta première session.')}</div></section></div>`;}
function chooseFocusMode(mode){if(focusSession&&!confirm('Abandonner la session sans l’enregistrer ?'))return;clearInterval(focusInt);focusSession=null;focusRunning=false;focusMode=mode;focusRemain=focusDuration(mode);persistFocus();syncFocusAlarm();render();}
function toggleFocus(){toggleFocusV5();syncFocusAlarm();}
function resetFocus(){if(focusSession&&!confirm('Abandonner cette session sans la comptabiliser ?'))return;clearInterval(focusInt);focusSession=null;focusRunning=false;focusRemain=focusDuration(focusMode);persistFocus();syncFocusAlarm();render();}
function finishPartialFocus(){if(!focusSession||focusSession.mode!=='work')return;if(focusSession.running){tickFocus();if(!focusSession)return;}const seconds=Math.max(0,focusSession.seconds-focusRemain);if(seconds<1)return toast('La session vient de commencer');if(!confirm(`Enregistrer ${Math.round(seconds/60*10)/10} minute(s) et terminer la session ?`))return;completeFocus(true);}
function completeFocus(partial=false){const r=focusSession;if(!r)return;clearInterval(focusInt);focusRunning=false;const seconds=partial?Math.max(0,r.seconds-focusRemain):r.seconds,minutes=Math.round(seconds/60*100)/100,[type,id]=r.selection.split(':');
 if(r.mode==='work'&&minutes>0&&!S.focus.some(f=>f.id===r.id)){const key={task:'tasks',habit:'habits',project:'projects',goal:'goals'}[type],x=key?S[key].find(x=>x.id===id):null,projectId=type==='project'?id:x?.projectId||'',goalId=type==='goal'?id:x?.goalId||S.projects.find(p=>p.id===projectId)?.goalId||'',date=partial?iso():iso(new Date(r.end));S.focus.push({id:r.id,date,minutes,type,refId:id||'',label:x?.title||'Session libre',projectId,goalId,partial:!!partial});if(type==='habit'&&x?.type==='timer'){S.habitLogs[id]??={};S.habitLogs[id][date]={value:Math.round((habitValue(id,date)+minutes)*100)/100,at:Date.now()};}if(!partial)S.settings.completedFocusCount=(S.settings.completedFocusCount||0)+1;save();}
 const wasLate=r.running&&Date.now()-(r.end||Date.now())>10000;focusSession=null;persistFocus();focusMode=r.mode==='work'&&!partial?((S.settings.completedFocusCount||0)%(S.settings.cycles||4)===0?'long':'break'):'work';focusRemain=focusDuration(focusMode);finishTone();syncFocusAlarm();toast(partial?'Temps réalisé enregistré':r.mode==='work'?'Session enregistrée':'Pause terminée');render();if(S.settings.autoCycles&&!partial&&!wasLate&&!document.hidden)setTimeout(()=>{if(!focusSession)toggleFocus();},500);}
let customAudio=null,customAudioURL=null;
function chooseAudio(){const i=document.createElement('input');i.type='file';i.accept='audio/*';i.onchange=()=>{const f=i.files[0];if(!f)return;if(f.size>50*1024*1024)return alert('Fichier audio trop volumineux (50 Mo maximum).');stopSound();if(customAudioURL)URL.revokeObjectURL(customAudioURL);customAudioURL=URL.createObjectURL(f);customAudio=new Audio(customAudioURL);customAudio.loop=true;customAudio.volume=S.settings.volume;customAudio.play().then(()=>{S.settings.sound='custom';save();render();}).catch(()=>alert('Ce format audio ne peut pas être lu. Essaie un MP3 ou un WAV.'));};i.click();}
function stopSound(){stopSoundV5();customAudio?.pause();}
function setVolume(v){S.settings.volume=+v;save();if(noiseNode?.gain)noiseNode.gain.value=S.settings.volume*.25;if(customAudio)customAudio.volume=S.settings.volume;}
function openTimerSettings(){modal('Durées & cycles',`<div class="formgrid"><div><label>Focus (min)</label><input id="set_focus" type="number" min="1" max="240" value="${S.settings.focus}"></div><div><label>Pause courte (min)</label><input id="set_break" type="number" min="1" max="240" value="${S.settings.break}"></div><div><label>Pause longue (min)</label><input id="set_long" type="number" min="1" max="240" value="${S.settings.long}"></div><div><label>Sessions avant pause longue</label><input id="set_cycles" type="number" min="2" max="10" value="${S.settings.cycles}"></div></div>`,`<button class="btn" onclick="closeModal()">Annuler</button><button class="btn primary" onclick="saveSettings()">Enregistrer</button>`);}
function saveSettings(){const f=+$('#set_focus').value,b=+$('#set_break').value,l=+$('#set_long').value,c=+$('#set_cycles').value;if(![f,b,l].every(n=>Number.isInteger(n)&&n>=1&&n<=240)||!Number.isInteger(c)||c<2||c>10)return toast('Durées de 1 à 240 min et cycles de 2 à 10');Object.assign(S.settings,{focus:f,break:b,long:l,cycles:c});save();if(!focusSession)focusRemain=focusDuration(focusMode);closeModal();render();}
function renderSettings(){return settingsV5()+`<div class="grid g2" style="margin-top:20px"><section class="card"><h3>Rappels & alertes</h3><p class="muted">Les rappels des tâches et habitudes et l’alerte de fin de focus utilisent les notifications Android.</p>${isNative()?`<p class="statusLine">${esc(reminderStatus)}</p><div class="chips"><button class="btn primary" onclick="enableReminders(${!S.settings.notifications})">${S.settings.notifications?'Désactiver':'Autoriser'} les rappels</button><button class="btn" onclick="exactAlarmSettings()">Réglage Android des alarmes</button></div><p class="muted caption">Sans autorisation d’alarme exacte, Android peut décaler l’heure. Les rappels quotidiens et hebdomadaires se répètent sans ouvrir l’application. Les rappels mensuels couvrent les 12 prochains mois et sont actualisés à chaque ouverture ; les prochaines tâches récurrentes sont créées quand tu termines l’occurrence actuelle.</p>`:'<p class="statusLine">Rappels en arrière-plan disponibles dans l’APK Android.</p>'}</section><section class="card"><h3>Une interface à ton rythme</h3><label>Densité</label><select id="prefDensity"><option value="comfortable" ${S.settings.density==='comfortable'?'selected':''}>Confortable</option><option value="compact" ${S.settings.density==='compact'?'selected':''}>Compacte</option></select><label style="margin-top:14px">Mes trois raccourcis mobiles</label><div class="formgrid">${[0,1,2].map(i=>`<select id="favorite${i}" aria-label="Raccourci ${i+1}">${navs.filter(n=>n[0]!=='today').map(n=>`<option value="${n[0]}" ${S.settings.favorites[i]===n[0]?'selected':''}>${n[2]}</option>`).join('')}</select>`).join('')}</div><label style="margin-top:14px">Domaines de vie — un par ligne</label><textarea id="lifeDomains">${esc(S.settings.domains.join('\n'))}</textarea><button class="btn primary" style="margin-top:12px" onclick="savePreferences()">Enregistrer mes préférences</button></section></div>`;}
function savePreferences(){const favorites=[0,1,2].map(i=>$('#favorite'+i).value);if(new Set(favorites).size!==3)return toast('Choisis trois raccourcis différents');const domains=[...new Set($('#lifeDomains').value.split('\n').map(x=>x.trim()).filter(Boolean))];if(!domains.length||domains.length>30||domains.some(x=>x.length>60))return toast('Ajoute 1 à 30 domaines de 60 caractères maximum');Object.assign(S.settings,{favorites,domains,density:$('#prefDensity').value});save();applyPreferences();renderNav();render();toast('Préférences enregistrées');}
function renderData(){return dataV5()+`<section class="card" style="margin-top:20px"><div class="sectionhead"><h3>Corbeille</h3><span class="tag">${S.trash.length} élément(s)</span></div><p class="muted">Les éléments supprimés restent récupérables jusqu’à leur suppression définitive. Les liaisons sont rétablies seulement si elles n’ont pas été réaffectées depuis.</p><div class="list">${S.trash.map(x=>`<div class="item"><div class="grow"><b>${esc(x.item.title||x.item.date||'Entrée')}</b><small>${{task:'Tâche',goal:'Objectif',project:'Projet',habit:'Habitude',journal:'Journal'}[x.type]} · ${esc(localDay(x.deletedAt))}</small></div><button class="btn" onclick="restoreTrash('${x.id}')">Restaurer</button><button class="btn danger" onclick="purgeTrash('${x.id}')">Effacer</button></div>`).join('')||empty('La corbeille est vide.')}</div></section>`;}
async function applyBackup(raw){const restored=await applyBackupV5(raw);S=upgradeState(S);applyPreferences();renderNav();render();syncReminders();return restored;}
function resetBusinessData(){return resetBusinessDataV5().then(()=>{S=upgradeState(S);applyPreferences();renderNav();render();syncReminders();});}
function bootV6(){bootV5();captureGoalHistory();syncReminders();if(isNative()){
 try{window.Capacitor.nativeCallback('LocalNotifications','addListener',{eventName:'localNotificationActionPerformed'},(data,error)=>{if(error)return;const x=data?.notification?.extra;if(x?.type==='task'&&S.tasks.some(t=>t.id===x.id)){go('tasks');openTask(x.id);}else if(x?.type==='habit'){go('habits');}else if(x?.type==='focus')go('focus');});}catch{}}
}

// LifeOS V6 improvements: icons, guided execution, lists, timer controls and practical guide.
const goalIconSet=[['🎯','Cible'],['🏆','Réussite'],['🌱','Croissance'],['💼','Carrière'],['💰','Finances'],['❤️','Santé'],['🏠','Famille'],['📚','Études'],['✈️','Voyage'],['🧘','Équilibre'],['🤝','Relations'],['🎨','Créativité'],['🧠','Développement'],['🏃','Forme'],['🛠️','Projet'],['🧭','Direction'],['💡','Idée'],['🌍','Impact']];
const habitIconSet=[['🔁','Routine'],['💧','Hydratation'],['🏃','Sport'],['📖','Lecture'],['🧘','Méditation'],['💊','Santé'],['😴','Sommeil'],['✍️','Écriture'],['🧹','Maison'],['🙏','Prière'],['🥗','Alimentation'],['🎸','Pratique'],['🚶','Marche'],['💰','Épargne'],['🧠','Apprentissage'],['🌳','Nature'],['📵','Déconnexion'],['📅','Planification']];
function iconPickerHtml(field,value,items){
 const selected=value||items[0][0];
 return '<div class="iconPicker" role="group" aria-label="Choisir une icône">'+items.map(([emoji,label])=>'<button type="button" class="iconPick '+(selected===emoji?'selected':'')+'" data-for="'+field+'" data-icon="'+esc(emoji)+'" title="'+esc(label)+'" aria-label="'+esc(label)+'" onclick="setEntityIcon(\''+field+'\',\''+esc(emoji)+'\')">'+emoji+'</button>').join('')+'</div><input type="hidden" id="'+field+'" value="'+esc(selected)+'">';
}
function setEntityIcon(field,value){
 const input=$('#'+field);if(!input)return;input.value=value;
 document.querySelectorAll('[data-for="'+field+'"]').forEach(b=>b.classList.toggle('selected',b.dataset.icon===value));
}
function goalWizard(g){
 let html=goalWizardBaseV6(g);
 html=html.replace('</div><div><label>Domaine de vie',iconPickerHtml('g_icon',g.icon,goalIconSet)+'</div><div><label>Domaine de vie');
 html=html.replace('<p class="muted">Après création, lie des projets, tâches et habitudes à cet objectif.</p>','<div class="formgrid" style="margin-top:14px"><div class="span2"><label>Créer un projet lié (facultatif)</label><input id="g_project_title" maxlength="160" placeholder="Ex. Préparer une course de 5 km"></div><div class="span2"><label>Jalons de ce projet — une ligne par jalon</label><textarea id="g_milestones" placeholder="Courir 2 km sans arrêt — semaine 3&#10;Courir 4 km — semaine 6"></textarea></div></div><p class="muted">Tu peux créer ces éléments maintenant ou plus tard dans la fiche de l’objectif.</p>');
 html=html.replace('</textarea><div class="card flat" style="margin-top:14px">','</textarea><label style="margin-top:14px">Créer des tâches liées — une ligne par action</label><textarea id="g_action_tasks" placeholder="Préparer mes chaussures la veille&#10;Courir 25 minutes lundi"></textarea><div class="card flat" style="margin-top:14px">');
 return html;
}
function saveGoal(id){
 const title=$('#g_title').value.trim(),mode=$('#g_progress').value;
 if(!title){goalStep=0;showGoalStep();return toast('Décris ton objectif');}
 const start=Number($('#g_start').value),target=Number($('#g_target').value),value=Number($('#g_current').value);
 if(![start,target,value].every(Number.isFinite)||mode==='focus'&&target<=0)return toast('Mesures invalides ; la cible focus doit être positive');
 const old=S.goals.find(g=>g.id===id),projectTitle=$('#g_project_title')?.value.trim()||'';
 const milestoneLines=cleanLines($('#g_milestones')?.value||''),actionLines=cleanLines($('#g_action_tasks')?.value||'');
 if(milestoneLines.length>50||actionLines.length>50)return toast('Maximum 50 jalons et 50 tâches par objectif');
 const g={...old,id:id||uid(),title,icon:$('#g_icon')?.value||old?.icon||'🎯',area:$('#g_area').value,why:$('#g_why').value,deadline:$('#g_deadline').value,priority:$('#g_priority').value,start,target,current:value,unit:$('#g_unit').value,status:$('#g_status').value,obstacles:$('#g_obstacles').value,skills:$('#g_skills').value,support:$('#g_support').value,plan:$('#g_plan').value,daily:$('#g_daily').value,progressMode:mode,habitWindow:Number($('#g_window').value),history:old?.history||[],createdAt:old?.createdAt||iso()};
 const i=S.goals.findIndex(x=>x.id===id);if(i>=0)S.goals[i]=g;else S.goals.push(g);
 let projectId='';
 if(projectTitle){projectId=uid();S.projects.push({id:projectId,title:projectTitle,goalId:g.id,status:'active',deadline:g.deadline||'',notes:'Créé depuis le plan de l’objectif « '+g.title+' ».',milestones:milestoneLines.map(title=>({id:uid(),title,due:'',done:false}))});}
 const existing=new Set(S.tasks.filter(t=>t.goalId===g.id).map(t=>t.title.toLocaleLowerCase()));
 for(const taskTitle of uniqueLines(actionLines))if(!existing.has(taskTitle.toLocaleLowerCase()))S.tasks.push({id:uid(),title:taskTitle,goalId:g.id,projectId,due:'',dueTime:'',priority:'medium',status:'todo',estimate:25,notes:'',repeat:'none',subtasks:[],createdAt:iso(),completedAt:null});
 save();closeModal();render();toast('Objectif enregistré'+(projectId?' avec son projet':''));
}
function cleanLines(text){return String(text||'').split(/\r?\n/).map(x=>x.trim().replace(/^[-*•]\s*/, '')).filter(Boolean);}
function uniqueLines(lines){return lines.filter((x,i)=>lines.findIndex(y=>y.toLocaleLowerCase()===x.toLocaleLowerCase())===i);}
let goalFilters={q:'',status:'active',area:'all',priority:'all',sort:'priority'};
function filteredGoals(){
 let rows=S.goals.filter(g=>(!goalFilters.q||[g.title,g.why,g.area].join(' ').toLocaleLowerCase().includes(goalFilters.q.toLocaleLowerCase()))&&(goalFilters.status==='all'||g.status===goalFilters.status)&&(goalFilters.area==='all'||g.area===goalFilters.area)&&(goalFilters.priority==='all'||g.priority===goalFilters.priority));
 const rank={high:0,medium:1,low:2},cmp={title:(a,b)=>a.title.localeCompare(b.title),priority:(a,b)=>(rank[a.priority]??3)-(rank[b.priority]??3),deadline:(a,b)=>(a.deadline||'9999').localeCompare(b.deadline||'9999'),progress:(a,b)=>pctGoal(b)-pctGoal(a),progressLow:(a,b)=>pctGoal(a)-pctGoal(b)};
 return rows.sort(cmp[goalFilters.sort]||cmp.priority);
}
function renderGoals(){
 const areas=[...new Set([...(S.settings.domains||[]),...S.goals.map(g=>g.area).filter(Boolean)])];
 return '<div class="sectionhead"><div><div class="eyebrow">Clarifier puis agir</div><h2>Mes objectifs</h2><small class="muted">Choisis un résultat important, puis transforme-le en projets et prochaines actions.</small></div><button class="btn primary" onclick="openGoal()">＋ Nouvel objectif</button></div><div class="card flat filters"><input aria-label="Rechercher un objectif" placeholder="Rechercher un objectif…" value="'+esc(goalFilters.q)+'" oninput="goalFilters.q=this.value;refreshGoalCards()"><select aria-label="Filtrer par statut" onchange="goalFilters.status=this.value;refreshGoalCards()">'+[['active','Actifs'],['paused','En pause'],['done','Atteints'],['all','Tous les statuts']].map(([v,l])=>'<option value="'+v+'" '+(goalFilters.status===v?'selected':'')+'>'+l+'</option>').join('')+'</select><select aria-label="Filtrer par domaine" onchange="goalFilters.area=this.value;refreshGoalCards()"><option value="all">Tous les domaines</option>'+areas.map(x=>'<option value="'+esc(x)+'" '+(goalFilters.area===x?'selected':'')+'>'+esc(x)+'</option>').join('')+'</select><select aria-label="Filtrer par priorité" onchange="goalFilters.priority=this.value;refreshGoalCards()">'+[['all','Toutes priorités'],['high','Essentielle'],['medium','Importante'],['low','Secondaire']].map(([v,l])=>'<option value="'+v+'" '+(goalFilters.priority===v?'selected':'')+'>'+l+'</option>').join('')+'</select><select aria-label="Trier les objectifs" onchange="goalFilters.sort=this.value;refreshGoalCards()">'+[['priority','Priorité'],['deadline','Échéance'],['progress','Progression · forte d’abord'],['progressLow','Progression · faible d’abord'],['title','Nom']].map(([v,l])=>'<option value="'+v+'" '+(goalFilters.sort===v?'selected':'')+'>'+l+'</option>').join('')+'</select></div><p class="muted" id="goalCount">'+filteredGoals().length+' objectif(s)</p><div class="grid g2" id="goalCards">'+(filteredGoals().map(goalCard).join('')||empty('Crée ton premier objectif significatif.'))+'</div>';
}
function refreshGoalCards(){const a=filteredGoals();$('#goalCards').innerHTML=a.map(goalCard).join('')||empty('Aucun objectif pour ces filtres.');$('#goalCount').textContent=a.length+' objectif(s)';}
function goalCard(g){
 const p=pctGoal(g),ts=S.tasks.filter(t=>t.goalId===g.id);
 return '<article class="card goalcard"><div class="goalHeading"><span class="tag">'+esc(g.area||'Personnel')+'</span><strong>'+p+'%</strong></div><button class="goalTitle" onclick="goalDetails(\''+g.id+'\')"><span class="entityIcon" aria-hidden="true">'+esc(g.icon||'🎯')+'</span>'+esc(g.title)+'</button><p class="muted caption">'+(g.deadline?'Échéance '+esc(g.deadline):'Sans échéance')+' · '+({manual:'Mesure manuelle',tasks:'Tâches liées',habits:'Régularité',focus:'Minutes focus'}[g.progressMode]||'Mesure manuelle')+'</p><div class="progress"><span style="width:'+p+'%"></span></div><div class="linked" style="margin:14px 0"><span>'+ts.filter(t=>t.status==='done').length+'/'+ts.length+' tâches</span><span>'+S.projects.filter(x=>x.goalId===g.id).length+' projets</span><span>'+S.habits.filter(h=>h.goalId===g.id).length+' habitudes</span></div><div class="miniActions"><button onclick="goalDetails(\''+g.id+'\')">Plan d’action →</button>'+iconButton('edit','Modifier l’objectif','openGoal(\''+g.id+'\')')+iconButton('trash','Mettre à la corbeille',"del('goal','"+g.id+"')")+'</div></article>';
}
function goalDetailsBasic(id){
 const g=S.goals.find(g=>g.id===id);if(!g)return;
 const relatedProjects=S.projects.filter(p=>p.goalId===id);
 modal(esc((g.icon||'🎯')+' '+g.title),'<div class="eyebrow">'+esc(g.area)+' · '+pctGoal(g)+' %</div><p style="margin-top:12px">'+esc(g.why||'Précise pourquoi cet objectif compte pour toi.')+'</p><div class="chips"><button class="btn primary" onclick="openTask(\'\',{goalId:\''+id+'\'})">+ Action</button><button class="btn" onclick="openProject(\'\',{goalId:\''+id+'\'})">+ Projet</button><button class="btn" onclick="openHabit(\'\',{goalId:\''+id+'\'})">+ Habitude</button><button class="btn" onclick="openLinked(\''+id+'\')">Lier des éléments existants</button></div><h3 style="margin-top:24px">Plan · créer un projet et ses jalons</h3><div class="formgrid"><div class="span2"><label>Nom du projet</label><input id="goalProjectTitle" placeholder="Ex. Préparer une course de 5 km"></div><div class="span2"><label>Jalons — une ligne par jalon</label><textarea id="goalMilestones" placeholder="Courir 2 km — semaine 3&#10;Courir 4 km — semaine 6"></textarea></div></div><button class="btn" style="margin-top:10px" onclick="createGoalProject(\''+id+'\')">Créer le projet et ses jalons</button><p class="muted caption">'+relatedProjects.length+' projet(s) déjà lié(s). Après création, ouvre le projet pour ajouter dates et suivre ses jalons.</p><h3 style="margin-top:24px">Plan · transformer des étapes en tâches</h3><p class="muted">Une ligne par tâche. Les tâches déjà liées ne seront pas dupliquées.</p><textarea id="planLines">'+esc(g.plan||'')+'</textarea><button class="btn" style="margin-top:10px" onclick="createPlanTasks(\''+id+'\',\'planLines\')">Créer les tâches de mon plan</button><h3 style="margin-top:24px">Action · prochaines étapes</h3><textarea id="goalActions">'+esc(g.daily||'')+'</textarea><label>Associer au projet (facultatif)</label><select id="goalTaskProject"><option value="">Sans projet</option>'+relatedProjects.map(p=>'<option value="'+p.id+'">'+esc(p.title)+'</option>').join('')+'</select><button class="btn" style="margin-top:10px" onclick="createPlanTasks(\''+id+'\',\'goalActions\',\'goalTaskProject\')">Créer les tâches d’action</button><h3 style="margin-top:24px">Actions liées</h3><div class="list">'+taskList(S.tasks.filter(t=>t.goalId===id))||empty('Aucune action liée')+'</div><h3 style="margin-top:24px">Historique de progression</h3>'+goalHistoryChart(g)+'<div class="grid g2" style="margin-top:20px"><div><h4>Obstacles</h4><p>'+esc(g.obstacles||'—')+'</p><h4>Compétences</h4><p>'+esc(g.skills||'—')+'</p></div><div><h4>Soutien</h4><p>'+esc(g.support||'—')+'</p><h4>Action régulière</h4><p>'+esc(g.daily||'—')+'</p></div></div>','<button class="btn" onclick="openGoal(\''+id+'\')">Modifier</button><button class="btn primary" onclick="closeModal()">Fermer</button>',true);
}
function createGoalProject(gid){
 const g=S.goals.find(g=>g.id===gid),title=$('#goalProjectTitle').value.trim(),lines=cleanLines($('#goalMilestones').value);
 if(!title)return toast('Donne un nom au projet');if(lines.length>50)return toast('Maximum 50 jalons');
 const p={id:uid(),title,goalId:gid,status:'active',deadline:g?.deadline||'',notes:'Projet créé depuis l’objectif « '+(g?.title||'')+' ».',milestones:lines.map(title=>({id:uid(),title,due:'',done:false}))};
 S.projects.push(p);save();goalDetails(gid);toast('Projet créé avec '+lines.length+' jalon(s)');
}
function createPlanTasks(gid,sourceId='planLines',projectSelectId=''){
 const lines=cleanLines($('#'+sourceId)?.value||'');if(!lines.length)return toast('Ajoute au moins une action');if(lines.length>50)return toast('Maximum 50 actions par création');
 const existing=new Set(S.tasks.filter(t=>t.goalId===gid).map(t=>t.title.toLocaleLowerCase())),fresh=uniqueLines(lines).filter(x=>!existing.has(x.toLocaleLowerCase()));
 if(!fresh.length)return toast('Ces actions sont déjà liées à cet objectif');
 const projectId=projectSelectId?$('#'+projectSelectId).value:'';
 if(projectId&&!S.projects.some(p=>p.id===projectId&&p.goalId===gid))return toast('Choisis un projet lié à cet objectif');
 for(const title of fresh)S.tasks.push({id:uid(),title,goalId:gid,projectId,due:$('#'+sourceId+'_due')?.value||'',dueTime:'',priority:$('#'+sourceId+'_priority')?.value||'medium',status:'todo',estimate:25,notes:'',repeat:'none',subtasks:[],createdAt:iso(),completedAt:null});
 save();goalDetails(gid);toast(fresh.length+' tâche(s) créée(s)');
}
function openHabit(id='',preset={}){
 openHabitBaseV6(id,preset);
 const h=S.habits.find(x=>x.id===id)||{...preset,icon:preset.icon||'🔁'};
 const target=$('#h_title');if(!target)return;
 target.insertAdjacentHTML('afterend',iconPickerHtml('h_icon',h.icon,habitIconSet));
}
function saveHabit(id){
 const icon=$('#h_icon')?.value||S.habits.find(h=>h.id===id)?.icon||'🔁',title=$('#h_title')?.value.trim(),before=new Set(S.habits.map(h=>h.id));
 saveHabitBaseV6(id);
 const row=S.habits.find(h=>h.id===id)||S.habits.find(h=>!before.has(h.id)&&h.title===title);
 if(row){row.icon=icon;save();render();}
}
let habitFilters={q:'',status:'active',freq:'all',sort:'streak'};
function filteredHabits(){
 let rows=S.habits.filter(h=>(!habitFilters.q||[h.title,h.unit].join(' ').toLocaleLowerCase().includes(habitFilters.q.toLocaleLowerCase()))&&(habitFilters.status==='all'||(habitFilters.status==='paused'?(!h.active||pausedOn(h,iso())):(h.active&&!pausedOn(h,iso()))))&&(habitFilters.freq==='all'||h.freq===habitFilters.freq));
 const rate=h=>{const p=habitPeriod(h,lastN(30)[0],iso());return p.expected?p.done/p.expected:0};
 return rows.sort((a,b)=>habitFilters.sort==='name'?a.title.localeCompare(b.title):habitFilters.sort==='rate'?rate(b)-rate(a):streak(b.id)-streak(a.id));
}
function renderHabits(){
 return '<div class="sectionhead"><div><div class="eyebrow">Répéter avec intention</div><h2>Mes habitudes</h2><small class="muted">Choisis un rythme réaliste et suis tes progrès sans chercher la perfection.</small></div><button class="btn primary" onclick="openHabit()">+ Nouvelle habitude</button></div><div class="card flat filters"><input aria-label="Rechercher une habitude" placeholder="Rechercher une habitude…" value="'+esc(habitFilters.q)+'" oninput="habitFilters.q=this.value;refreshHabitCards()"><select aria-label="Filtrer les habitudes" onchange="habitFilters.status=this.value;refreshHabitCards()">'+[['active','Actives'],['paused','En pause'],['all','Toutes']].map(([v,l])=>'<option value="'+v+'" '+(habitFilters.status===v?'selected':'')+'>'+l+'</option>').join('')+'</select><select aria-label="Filtrer par fréquence" onchange="habitFilters.freq=this.value;refreshHabitCards()">'+[['all','Toutes fréquences'],['daily','Quotidienne'],['weekdays','Jours ouvrés'],['days','Jours choisis'],['weekly','Objectif hebdomadaire'],['monthly','Mensuelle']].map(([v,l])=>'<option value="'+v+'" '+(habitFilters.freq===v?'selected':'')+'>'+l+'</option>').join('')+'</select><select aria-label="Trier les habitudes" onchange="habitFilters.sort=this.value;refreshHabitCards()">'+[['streak','Série'],['rate','Régularité · forte d’abord'],['name','Nom']].map(([v,l])=>'<option value="'+v+'" '+(habitFilters.sort===v?'selected':'')+'>'+l+'</option>').join('')+'</select></div><p class="muted" id="habitCount">'+filteredHabits().length+' habitude(s)</p><div class="list" id="habitCards">'+filteredHabits().map(h=>{const p=habitPeriod(h,lastN(30)[0],iso());return '<div class="card">'+habitList([h])+'<div class="linked" style="margin-top:12px"><span>Série : '+streak(h.id)+' '+(h.freq==='weekly'?'semaines':'jours prévus')+'</span><span>30 jours : '+p.done+'/'+p.expected+' réalisations attendues</span><span>'+focusFor('habit',h.id)+' min focus</span></div></div>';}).join('')||empty('Aucune habitude pour ces filtres.')+'</div>';
}
function refreshHabitCards(){const a=filteredHabits();$('#habitCards').innerHTML=a.map(h=>{const p=habitPeriod(h,lastN(30)[0],iso());return '<div class="card">'+habitList([h])+'<div class="linked" style="margin-top:12px"><span>Série : '+streak(h.id)+' '+(h.freq==='weekly'?'semaines':'jours prévus')+'</span><span>30 jours : '+p.done+'/'+p.expected+' réalisations attendues</span><span>'+focusFor('habit',h.id)+' min focus</span></div></div>';}).join('')||empty('Aucune habitude pour ces filtres.');$('#habitCount').textContent=a.length+' habitude(s)';}
function habitList(arr){
 return arr.map(h=>{const planned=scheduled(h,iso()),paused=pausedOn(h,iso())||!h.active;return '<article class="item habitrow"><div><b><span class="entityIcon" aria-hidden="true">'+esc(h.icon||'🔁')+'</span>'+esc(h.title)+'</b><small class="muted">'+freqText(h)+' · '+habitValue(h.id,iso())+'/'+(h.type==='check'?1:h.target)+' '+esc(h.type==='timer'?'min':h.unit)+'</small><div class="weekdots">'+last7().map(d=>'<button class="daydot '+(habitDone(h.id,d)?'done':scheduled(h,d)?'':'unplanned')+'" title="'+d+' : '+habitValue(h.id,d)+'" aria-label="Réalisation du '+d+'" onclick="logHabit(\''+h.id+'\');$(\'#log_date\').value=\''+d+'\';$(\'#log_value\').value=habitValue(\''+h.id+'\',\''+d+'\')">'+(habitDone(h.id,d)?'✓':scheduled(h,d)?new Date(d+'T12:00').toLocaleDateString('fr',{weekday:'narrow'}):'—')+'</button>').join('')+'</div>'+(paused?'<span class="tag">En pause</span>':!planned?'<span class="tag">Non prévue aujourd’hui</span>':'')+'</div><div class="miniActions">'+(h.type==='timer'?iconButton('focus','Démarrer le minuteur','habitTimer(\''+h.id+'\')'):'')+'<button onclick="logHabit(\''+h.id+'\')">Saisir</button>'+iconButton('edit','Modifier','openHabit(\''+h.id+'\')')+'<button onclick="toggleHabitPause(\''+h.id+'\')">'+(paused?'Reprendre':'Pause')+'</button>'+iconButton('trash','Corbeille','del(\'habit\',\''+h.id+'\')')+'</div></article>';}).join('');
}
let milestoneFilters={};
function milestoneState(id){return milestoneFilters[id]||(milestoneFilters[id]={q:'',status:'all',sort:'date'});}
function milestoneRows(pid){
 const p=S.projects.find(x=>x.id===pid);if(!p)return empty('Projet introuvable');const f=milestoneState(pid);
 let rows=p.milestones.filter(m=>(!f.q||m.title.toLocaleLowerCase().includes(f.q.toLocaleLowerCase()))&&(f.status==='all'||(f.status==='done'?m.done:!m.done)));
 rows.sort((a,b)=>f.sort==='title'?a.title.localeCompare(b.title):(a.due||'9999').localeCompare(b.due||'9999')||a.title.localeCompare(b.title));
 return rows.map(m=>'<div class="item"><button class="check '+(m.done?'done':'')+'" aria-label="'+(m.done?'Marquer non terminé':'Terminer le jalon')+'" onclick="toggleMilestone(\''+pid+'\',\''+m.id+'\')">'+(m.done?'✓':'')+'</button><div class="grow"><b>'+esc(m.title)+'</b><small>'+esc(m.due||'Sans date')+'</small></div><button class="btn" onclick="editMilestone(\''+pid+'\',\''+m.id+'\')">Modifier</button></div>').join('')||empty('Aucun jalon ne correspond au filtre.');
}
function projectDetails(id){
 projectDetailsBaseV6(id);
 const heads=[...$('#modal').querySelectorAll('h3')],heading=heads.find(h=>h.textContent.trim()==='Jalons');if(!heading)return;
 const oldList=heading.nextElementSibling;if(!oldList)return;
 const f=milestoneState(id);
 heading.insertAdjacentHTML('afterend','<div class="milestoneFilters"><input aria-label="Rechercher un jalon" placeholder="Rechercher un jalon…" value="'+esc(f.q)+'" oninput="setMilestoneFilter(\''+id+'\',\'q\',this.value)"><select aria-label="Filtrer les jalons" onchange="setMilestoneFilter(\''+id+'\',\'status\',this.value)">'+[['all','Tous les jalons'],['open','À faire'],['done','Terminés']].map(([v,l])=>'<option value="'+v+'" '+(f.status===v?'selected':'')+'>'+l+'</option>').join('')+'</select><select aria-label="Trier les jalons" onchange="setMilestoneFilter(\''+id+'\',\'sort\',this.value)">'+[['date','Échéance'],['title','Nom']].map(([v,l])=>'<option value="'+v+'" '+(f.sort===v?'selected':'')+'>'+l+'</option>').join('')+'</select></div>');
 oldList.id='milestoneRows';oldList.innerHTML=milestoneRows(id);
}
function setMilestoneFilter(id,key,value){milestoneState(id)[key]=value;$('#milestoneRows').innerHTML=milestoneRows(id);}
function renderMore(){
 return '<div class="pageIntro"><div class="eyebrow">Tous tes espaces</div><h2>Que souhaites-tu faire ?</h2><p class="muted">Tes trois raccourcis favoris se règlent dans Paramètres. Le guide t’explique un parcours simple pour commencer.</p></div><div class="grid g2">'+navs.map(([id,,name])=>'<button class="card menuTile" onclick="go(\''+id+'\');if([\'settings\',\'data\'].includes(\''+id+'\'))refreshNative()">'+icon(id)+'<b>'+esc(name)+'</b>'+icon('arrow')+'</button>').join('')+'<button class="card menuTile" onclick="go(\'guide\')">'+icon('journal')+'<b>Guide pratique</b>'+icon('arrow')+'</button></div>';
}
function renderGuideShort(){
 return '<div class="pageIntro"><div class="eyebrow">Un parcours simple, sans tout faire d’un coup</div><h2>Guide pratique LifeOS</h2><p class="muted">Pars d’un résultat important, transforme-le en étapes concrètes et réserve du temps pour les réaliser.</p></div><section class="card guideIntro"><h3>Le fil de l’application</h3><p><b>Objectif → projet → jalons → tâches → créneaux → focus → revue.</b> Les habitudes soutiennent le parcours ; le journal et les statistiques t’aident à ajuster.</p><p class="muted">Tu peux commencer par une seule tâche ou une seule habitude. Le guide est une aide, pas une obligation.</p></section><div class="guideSteps"><article class="card guideStep"><span class="guideNumber">1</span><div><h3>Choisis un résultat clair</h3><p>Dans <b>Objectifs</b>, décris ce que tu veux obtenir, pourquoi cela compte et à quelle date tu veux faire le point. Choisis une icône qui te le rappelle.</p><div class="example"><b>Exemple :</b> « Courir 5 km sans m’arrêter d’ici 8 semaines », plutôt que « faire plus de sport ».</div></div></article><article class="card guideStep"><span class="guideNumber">2</span><div><h3>Écris le plan et découpe-le</h3><p>Dans le formulaire de l’objectif, l’onglet <b>Plan</b> peut créer un projet et ses jalons. Dans <b>Action</b>, ajoute les prochaines tâches, une par ligne. Dans la fiche, tu peux encore créer des jalons et convertir un plan en tâches.</p><div class="example"><b>Exemple :</b> projet « Préparation 5 km » ; jalons « 2 km en semaine 3 », puis « 4 km en semaine 6 » ; tâches « choisir un parcours », « courir 25 min lundi ».</div></div></article><article class="card guideStep"><span class="guideNumber">3</span><div><h3>Décide de la priorité avant de remplir la journée</h3><p>LifeOS reprend une idée de Brian Tracy : repérer l’action qui rapproche le plus du résultat important et commencer par elle. Dans <b>Tâches</b>, règle la priorité, puis l’échéance et l’heure. Garde la liste du jour réaliste.</p><div class="example"><b>Exemple :</b> si l’objectif est de préparer un examen, faire un exercice d’annale peut compter davantage que ranger ses notes.</div></div></article><article class="card guideStep"><span class="guideNumber">4</span><div><h3>Réserve un créneau et concentre-toi</h3><p>Dans <b>Calendrier</b>, place l’action. Ouvre <b>Focus</b>, associe le minuteur à la tâche, puis fais une seule chose pendant le temps choisi. Le réglage courant par défaut est 25 min de travail et 5 min de pause, modifiable dans les réglages.</p><div class="example"><b>Exemple :</b> 25 minutes sur « rédiger le plan », 5 minutes de pause, puis décide si tu continues.</div></div></article><article class="card guideStep"><span class="guideNumber">5</span><div><h3>Installe un rythme soutenable</h3><p>Crée dans <b>Habitudes</b> une routine précise et adaptée à tes contraintes. Tu peux choisir des jours, une cible hebdomadaire ou des dates du mois. Une pause est possible : reprendre compte plus que viser une série parfaite.</p><div class="example"><b>Exemple :</b> « Lire 10 minutes, lundi à vendredi » ; règle le suivi et la fréquence selon ton usage.</div></div></article><article class="card guideStep"><span class="guideNumber">6</span><div><h3>Fais un point bref, puis ajuste</h3><p>Le soir, coche les actions réalisées et note une idée dans le <b>Journal</b>. Une fois par semaine, ouvre la <b>Revue</b> : qu’est-ce qui a avancé, qu’est-ce qui a bloqué, quelle est la prochaine action essentielle ? Les statistiques décrivent les données enregistrées ; elles ne jugent pas tes progrès.</p><div class="example"><b>Exemple :</b> si les entraînements du soir ne passent pas, essaie un créneau plus court le matin.</div></div></article></div><section class="card"><h3>La méthode en une minute</h3><ol><li>Choisis un objectif important et mesurable.</li><li>Crée un projet avec quelques jalons, puis des tâches courtes.</li><li>Choisis une priorité et réserve-lui un créneau.</li><li>Fais une séance de focus, puis enregistre ce qui a réellement été fait.</li><li>Revois le plan chaque semaine et adapte-le sans culpabiliser.</li></ol><p class="muted caption">Cette présentation reformule des principes de planification, de priorisation et de passage à l’action associés à Brian Tracy. Elle n’est pas un conseil personnalisé ni un texte reproduit de ses ouvrages.</p><div class="chips"><a class="btn" href="https://www.briantracy.com/blog/time-management/productivity-tips/" target="_blank" rel="noopener">Brian Tracy · Productivité</a><a class="btn" href="https://www.briantracy.com/blog/time-management/the-truth-about-frogs/" target="_blank" rel="noopener">Brian Tracy · Eat That Frog</a></div></section>';
}
function base_render(){
 const f={today:renderToday,goals:renderGoals,projects:renderProjects,tasks:renderTasks,habits:renderHabits,planner:renderPlanner,focus:renderFocus,journal:renderJournal,stats:renderStats,coach:renderCoach,data:renderData,settings:renderSettings,more:renderMore,guide:renderGuide}[current];
 $('#content').innerHTML=f?f():'';
}
function updateClock(){const x=$('#focusClock');if(x)x.textContent=fmt(focusRemain);}
function toggleFocus(){
 if(!focusSession){
  focusSelection=$('#focusLink')?.value||focusSelection||'free:';
  focusSession={id:uid(),selection:focusSelection,seconds:Math.max(1,Number(focusRemain)||1),remaining:Math.max(1,Number(focusRemain)||1),mode:focusMode,started:Date.now(),running:false};
 }
 if(focusRunning||focusSession.running){
  if(focusSession.running)focusRemain=Math.max(0,Math.ceil((focusSession.end-Date.now())/1000));
  if(focusRemain<=0){completeFocus();return;}
  focusSession.remaining=focusRemain;focusSession.running=false;focusRunning=false;clearInterval(focusInt);focusInt=null;
 }else{
  const remain=Math.max(0,Number(focusSession.remaining??focusRemain)||0);
  if(remain<=0){completeFocus();return;}
  focusRemain=remain;focusSession.end=Date.now()+remain*1000;focusSession.running=true;focusRunning=true;clearInterval(focusInt);focusInt=setInterval(tickFocus,250);
 }
 persistFocus();updateClock();render();syncFocusAlarm();
}
function elapsedFocusSeconds(){if(!focusSession)return 0;const remain=focusSession.running?Math.max(0,Math.ceil((focusSession.end-Date.now())/1000)):focusRemain;return Math.max(0,(Number(focusSession.seconds)||0)-remain);}
function resetFocus(){
 const elapsed=elapsedFocusSeconds();if(elapsed>0&&!confirm('Réinitialiser et abandonner les '+Math.ceil(elapsed/60)+' minute(s) déjà écoulées ?'))return;
 clearInterval(focusInt);focusInt=null;focusSession=null;focusRunning=false;focusRemain=focusDuration(focusMode);persistFocus();syncFocusAlarm();render();toast('Minuteur réinitialisé');
}
function finishPartialFocus(){
 if(!focusSession)return toast('Démarre une session avant de terminer.'); if(focusSession.mode!=='work'){completeFocus(true);return;}
 if(focusSession.running){focusRemain=Math.max(0,Math.ceil((focusSession.end-Date.now())/1000));if(focusRemain<=0){completeFocus();return;}focusSession.remaining=focusRemain;focusSession.running=false;focusRunning=false;clearInterval(focusInt);focusInt=null;}
 const seconds=elapsedFocusSeconds();if(seconds<1)return toast('Quelques secondes doivent être écoulées avant d’enregistrer.');
 completeFocus(true);
}
function completeFocus(partial=false){
 const r=focusSession;if(!r)return;
 clearInterval(focusInt);focusInt=null;focusRunning=false;
 const total=Math.max(0,Number(r.seconds)||0),seconds=partial?elapsedFocusSeconds():total,minutes=Math.round(seconds/60*100)/100;
 if(partial&&r.mode==='work'&&seconds<1)return toast('Quelques secondes doivent être écoulées avant d’enregistrer.');
 const [type,id]=String(r.selection||'free:').split(':'),isWork=r.mode==='work';
 if(isWork&&minutes>0&&!S.focus.some(f=>f.id===r.id)){
  const key={task:'tasks',habit:'habits',project:'projects',goal:'goals'}[type],x=key?S[key].find(x=>x.id===id):null;
  const projectId=type==='project'?id:(x?.projectId||''),goalId=type==='goal'?id:(x?.goalId||S.projects.find(p=>p.id===projectId)?.goalId||'');
  S.focus.push({id:r.id,date:partial?iso():iso(new Date(r.end||Date.now())),minutes,type,refId:id||'',label:x?.title||'Session libre',projectId,goalId,partial:!!partial});
  if(type==='habit'&&x?.type==='timer'){S.habitLogs[id]??={};S.habitLogs[id][iso()]={value:Math.round((habitValue(id,iso())+minutes)*100)/100,at:Date.now()};}
  if(!partial)S.settings.completedFocusCount=(S.settings.completedFocusCount||0)+1;save();
 }
 const wasLate=!!r.running&&Date.now()-(r.end||Date.now())>10000;
 focusSession=null;focusRunning=false;persistFocus();
 focusMode=isWork&&!partial?((S.settings.completedFocusCount||0)%(S.settings.cycles||4)===0?'long':'break'):'work';
 focusRemain=focusDuration(focusMode);finishTone();syncFocusAlarm();
 toast(partial?'Temps réalisé enregistré':isWork?'Session enregistrée':'Pause terminée');render();
 if(S.settings.autoCycles&&!partial&&!wasLate&&!document.hidden)setTimeout(()=>{if(!focusSession)toggleFocus();},500);
}

function openTask(id='',preset={}){openTaskBasic(id,preset);const t=S.tasks.find(t=>t.id===id)||preset;$('#f_project').insertAdjacentHTML('afterend','<label style="margin-top:12px">Jalon</label><select id="f_milestone"></select>');updateTaskMilestones(t.milestoneId);}
function updateTaskMilestones(selected=''){const el=$('#f_milestone');if(!el)return;const p=S.projects.find(p=>p.id===$('#f_project').value);el.innerHTML='<option value="">Sans jalon</option>'+(p?.milestones||[]).map(m=>'<option value="'+m.id+'">'+esc(m.title)+'</option>').join('');el.value=selected||'';}
function goalDetails(id){goalDetailsBasic(id);const g=S.goals.find(g=>g.id===id);if(!g)return;const ps=S.projects.filter(p=>p.goalId===id);$('#modal .modalBody').insertAdjacentHTML('beforeend','<section class="card" style="margin-top:20px"><h3>Gérer le plan existant</h3>'+ps.map(p=>'<div class="item"><div class="grow"><b>'+esc(p.title)+'</b><small>'+p.milestones.length+' jalons</small></div><button class="btn" onclick="projectDetails(\''+p.id+'\')">Ouvrir</button><button class="btn" onclick="editMilestone(\''+p.id+'\')">+ Jalon daté</button><button class="btn" onclick="openTask(\'\',{goalId:\''+id+'\',projectId:\''+p.id+'\'})">+ Tâche détaillée</button></div>'+p.milestones.map(m=>'<div class="item"><div class="grow">'+esc(m.title)+' · '+esc(m.due||'Sans date')+'</div><button class="btn" onclick="editMilestone(\''+p.id+'\',\''+m.id+'\')">Modifier</button><button class="btn" onclick="openTask(\'\',{goalId:\''+id+'\',projectId:\''+p.id+'\',milestoneId:\''+m.id+'\'})">+ Tâche</button></div>').join('')).join('')+'</section>');for(const field of ['planLines','goalActions']){const el=$('#'+field);el.insertAdjacentHTML('afterend','<div class="formgrid"><div><label>Échéance des tâches créées</label><input type="date" id="'+field+'_due"></div><div><label>Priorité</label><select id="'+field+'_priority"><option value="high">Haute</option><option value="medium" selected>Normale</option><option value="low">Basse</option></select></div></div>');}}
let projectFilters={q:'',status:'all',goal:'all',sort:'date',view:'projects'};
function renderProjects(){return '<div class="sectionhead"><div><div class="eyebrow">Structurer et suivre</div><h2>Projets & jalons</h2></div><button class="btn primary" onclick="openProject()">+ Nouveau projet</button></div><div class="card flat filters"><input aria-label="Rechercher projets et jalons" placeholder="Rechercher…" value="'+esc(projectFilters.q)+'" oninput="projectFilters.q=this.value;refreshProjects()">'+projectSelect('view',[['projects','Projets'],['milestones','Tous les jalons']])+projectSelect('status',[['all','Tous les statuts'],['active','Actifs / à faire'],['paused','En pause'],['done','Terminés'],['late','En retard']])+projectSelect('goal',[['all','Tous les objectifs'],...S.goals.map(g=>[g.id,g.title])])+projectSelect('sort',[['date','Échéance'],['title','Nom']])+'</div><div id="projectsResults" class="list" style="margin-top:16px">'+projectResults()+'</div>';}
function projectSelect(key,options){return '<select aria-label="'+key+'" onchange="projectFilters.'+key+'=this.value;refreshProjects()">'+options.map(([v,l])=>'<option value="'+v+'" '+(projectFilters[key]===v?'selected':'')+'>'+esc(l)+'</option>').join('')+'</select>';}
function projectResults(){const f=projectFilters;let rows=f.view==='projects'?S.projects.map(p=>({p,title:p.title,due:p.deadline,status:p.status})):S.projects.flatMap(p=>p.milestones.map(m=>({p,m,title:m.title,due:m.due,status:m.done?'done':'active'})));rows=rows.filter(r=>(f.goal==='all'||r.p.goalId===f.goal)&&(!f.q||(r.title+' '+r.p.title).toLowerCase().includes(f.q.toLowerCase()))&&(f.status==='all'||(f.status==='late'?r.status!=='done'&&r.due&&r.due<iso():r.status===f.status)));rows.sort((a,b)=>f.sort==='title'?a.title.localeCompare(b.title):(a.due||'9999').localeCompare(b.due||'9999'));return '<p class="muted">'+rows.length+' résultat(s)</p>'+ (rows.map(r=>'<article class="item"><div class="grow"><b>'+esc(r.title)+'</b><small>'+esc(goalName(r.p.goalId)||'Sans objectif')+' · '+(r.m?esc(r.p.title)+' · ':'')+esc(r.due||'Sans échéance')+' · '+({active:'À faire',paused:'En pause',done:'Terminé'}[r.status]||r.status)+'</small></div><button class="btn" onclick="'+(r.m?'editMilestone(\''+r.p.id+'\',\''+r.m.id+'\')':'projectDetails(\''+r.p.id+'\')')+'">Ouvrir</button></article>').join('')||empty('Aucun résultat pour ces filtres.'));}
function refreshProjects(){$('#projectsResults').innerHTML=projectResults();}
function renderGuide(){return renderGuideShort()+'<section class="card" style="margin-top:20px"><h3>Utiliser chaque espace</h3>'+[
['Aujourd’hui et tâches','Prépare la veille les actions de demain. Choisis une tâche essentielle, donne-lui une priorité haute, une date et une durée réaliste. Exemple : préparer le rapport mensuel à 9 h pendant 45 minutes. Ouvre la tâche pour ajouter des sous-tâches, une récurrence ou un jalon.'],
['Un plan complet','Objectif : terminer mon rapport mensuel le 7. Projet : clôture du mois. Jalons : rapprochements le 3, contrôles le 5, validation le 7. Sous chaque jalon, crée les tâches correspondantes avec échéance et priorité. Dans la fiche objectif, Gérer le plan existant permet d’ajouter des jalons datés et des tâches détaillées.'],
['Brian Tracy : choisir avant d’agir','Clarifie ton résultat par écrit, découpe-le, puis identifie la prochaine action ayant le plus de conséquences utiles. Prépare ta liste avant de commencer. Une application pratique de Eat That Frog consiste à réserver ton meilleur créneau à cette action. Les priorités haute, normale et basse de LifeOS sont un classement simplifié ; elles ne constituent pas une méthode ABCDE complète.'],
['Pomodoro','Démarrer lance la phase choisie ; Mettre en pause suspend le compte à rebours ; Reprendre continue. Terminer & enregistrer conserve le temps de concentration effectué. Terminer la pause revient au travail sans ajouter de minutes productives. Réinitialiser abandonne le temps non enregistré après confirmation et remet la durée de la phase.'],
['Habitudes','Choisis un rythme et un type de mesure : case à cocher, quantité ou minutes. Exemple : lire 10 minutes les jours ouvrés. Saisir permet de corriger une date antérieure. Une pause suspend la routine. Les séries et taux reposent sur les réalisations enregistrées.'],
['Calendrier, journal et revue','Le calendrier présente les tâches datées et les échéances. Le journal conserve tes observations. Pendant la revue hebdomadaire, regarde les retards, adapte les échéances et choisis la prochaine priorité. Exemple : découper une tâche reportée trois fois en deux actions de 20 minutes.'],
['Statistiques et progression','Choisis le mode de progression de chaque objectif : mesure manuelle, tâches terminées, habitudes ou minutes focus. Ajouter des tâches peut faire baisser un pourcentage sans effacer le travail accompli. Vérifie la période et le mode avant de comparer les résultats.'],
['Réglages et sécurité','Dans Paramètres, personnalise le thème, la densité, les raccourcis et les durées. La biométrie dépend du support Android natif : un fichier HTML ouvert seul ne fournit pas toutes les fonctions de l’APK. Ne confonds pas verrouillage de l’accès et chiffrement des sauvegardes.'],
['Sauvegarder et restaurer','Dans Données & sauvegardes, exporte régulièrement un JSON ou une sauvegarde protégée par mot de passe. Garde une copie hors de l’appareil. Avant une restauration, exporte les données actuelles : restaurer peut les remplacer. Un point local de restauration ne remplace pas une copie externe. Le fichier HTML de l’application ne contient pas automatiquement tes données personnelles.'],
['Recherche et filtres','Objectifs : statut, domaine, priorité et progression. Habitudes : statut, fréquence et régularité. Tâches : statut, priorité, projet et échéance. Projets & jalons : bascule entre projets et tous les jalons, puis filtre par objectif ou retard. Si un élément paraît absent, vérifie les filtres actifs.']
].map(([t,p])=>'<details class="guideDetail"><summary>'+t+'</summary><p>'+p+'</p></details>').join('')+'</section>';}

// Bulk task triage: select the current results and apply one change to the group.
function updateTaskTriage(visible=filteredTasks()){
 const count=selectedTaskIds.size, label=$('#selectedTaskCount'), actions=$('#triageActions'), select=$('#selectVisibleTasks');
 if(label)label.textContent=count+' tâche'+(count===1?'':'s')+' sélectionnée'+(count===1?'':'s');
 if(actions)actions.hidden=count===0;
 if(select){const ids=visible.map(t=>t.id),picked=ids.filter(id=>selectedTaskIds.has(id)).length;select.checked=ids.length>0&&picked===ids.length;select.indeterminate=picked>0&&picked<ids.length;}
}
function toggleTaskSelection(id,checked){if(checked)selectedTaskIds.add(id);else selectedTaskIds.delete(id);refreshTaskList();}
function selectVisibleTasks(checked){for(const t of filteredTasks())checked?selectedTaskIds.add(t.id):selectedTaskIds.delete(t.id);refreshTaskList();}
function selectedTasks(){return S.tasks.filter(t=>selectedTaskIds.has(t.id));}
function finishTaskTriage(message){selectedTaskIds.clear();save();render();toast(message);}
function applyBulkTaskStatus(){const status=$('#bulkTaskStatus').value,items=selectedTasks();if(!status||!items.length)return toast('Choisis un statut et au moins une tâche');if(status==='done'&&!confirm('Terminer '+items.length+' tâche(s) sélectionnée(s) ? Les tâches récurrentes créeront leur prochaine occurrence.'))return;for(const t of items)setTaskStatus(t.id,status,{silent:true});finishTaskTriage(items.length+' tâche(s) mise(s) à jour');}
function applyBulkTaskPriority(){const priority=$('#bulkTaskPriority').value,items=selectedTasks();if(!priority||!items.length)return toast('Choisis une priorité et au moins une tâche');for(const t of items)t.priority=priority;finishTaskTriage('Priorité mise à jour pour '+items.length+' tâche(s)');}
function applyBulkTaskDue(){const due=$('#bulkTaskDue').value,items=selectedTasks();if(!/^\d{4}-\d{2}-\d{2}$/.test(due)||!items.length)return toast('Choisis une échéance valide et au moins une tâche');for(const t of items)t.due=due;finishTaskTriage(items.length+' tâche(s) planifiée(s)');}
function postponeSelectedTasks(){const items=selectedTasks().filter(t=>t.status!=='done');if(!items.length)return toast('Aucune tâche ouverte sélectionnée');for(const t of items)t.due=addDays(1);finishTaskTriage(items.length+' tâche(s) reportée(s) à demain');}

init();
bootV6();
try{const r=JSON.parse(localStorage.getItem('lifeos.timer.v4')||'null');if(r&&Number.isFinite(r.seconds)&&r.seconds>0&&r.seconds<=14400&&Number.isFinite(r.remaining)&&typeof r.selection==='string'&&(!r.running||Number.isFinite(r.end))){focusSession=r;focusSelection=r.selection;focusMode=r.mode;focusRunning=!!r.running;focusRemain=r.remaining;if(r.running){focusInt=setInterval(tickFocus,250);tickFocus();}}}catch(e){}
if(window.lifeLoadError)alert('La sauvegarde locale est illisible. Elle a été conservée. Importe une sauvegarde JSON valide avant de saisir de nouvelles données.');
